// Üretilen dosya: tool/ozgun/uret.py. Bilişim ve Algoritmalar · Eşzamanlılık (yarış durumu, kilitlenme, semafor), sanal bellek, önbellek (cache) yerelliği, boru hattı (pipelining) ve dosya sistemleri (orta).
const ozComputing18Orta = <(String, String, List<String>, String)>[
  ('Başlangıç değeri c = 10 olan paylaşılan bir değişkene iki iş parçacığı kilitsiz olarak birer kez c = c + 1 ve c = c - 1 uygularsa c işlem sonunda hangi değerleri alabilir?', '9, 10 veya 11', ['Yalnızca 10', 'Yalnızca 9 veya 11', '8, 10 veya 12'], 'İki işlem sıralı çalışırsa sonuç 10 olur; ancak ikisi de 10 değerini okuyup sırayla yazarsa son yazana göre sonuç 9 veya 11 kalabilir.'),
  ('Mutex ile ikili semafor (binary semaphore) arasındaki en temel yapısal fark aşağıdakilerden hangisidir?', 'Mutex\'te sahiplik kavramı vardır ve kilidi yalnızca alan iş parçacığı açabilir', ['İkili semafor yalnızca tek çekirdekli işlemcilerde karşılıklı dışlama sağlayabilir', 'Mutex sayacı 10\'a kadar çıkabilirken ikili semafor yalnızca negatif değer alır', 'İkili semaforda bekleyen iş parçacıkları hiçbir zaman uyku durumuna geçirilemez'], 'Mutex kilidinde sahiplik (ownership) ilkesi geçerlidir; kilidi hangi iş parçacığı almışsa yalnızca o serbest bırakabilir, semaforda ise başka bir iş parçacığı signal çağırabilir.'),
  ('İki süreç birbirinden yalıtılmış adres uzaylarına sahipken aralarında veri paylaşmak istediklerinde hangi mekanizmayı kullanmalıdır?', 'Süreçler Arası İletişim', ['Aynı yerel yığın (stack) işaretçisini doğrudan birbirine atama', 'Fonksiyon içi yerel değişkenleri küresel yazmaçlara kopyalama', 'Derleyici optimizasyonuyla iki süreci tek bir alt yordama dönüştürme'], 'Süreçlerin bellek alanları işletim sistemince izole edildiğinden veri alışverişi paylaşılan bellek (shared memory), boru (pipe) veya mesaj kuyruğu gibi IPC yöntemleriyle yapılır.'),
  ('Başlangıç değeri 3 olan bir sayma semaforu üzerinde sırasıyla 5 kez wait(P) ve 2 kez signal(V) çağrısı yapılırsa kaç iş parçacığı bloke durumda kalır?', '0', ['2 iş parçacığı bloke durumda kalır', '3 iş parçacığı bloke durumda kalır', '1 iş parçacığı bloke durumda kalır'], 'İlk 3 wait kaynağı alır (sayaç 0 olur), sonraki 2 wait iki iş parçacığını bloke eder; ardından gelen 2 signal bu iki bekleyen iş parçacığını uyandırır ve bloke kimse kalmaz.'),
  ('Başlangıç değeri 2 olan bir sayma semaforuna 6 farklı iş parçacığı wait(P) ve 1 iş parçacığı signal(V) uygularsa kuyrukta bekleyen iş parçacığı sayısı kaç olur?', '3', ['4', '2', '1'], 'İlk 2 wait başarılı olur, kalan 4 wait kuyruğa girer; yapılan 1 adet signal bekleyenlerden birini uyandırdığı için kuyrukta 3 iş parçacığı kalır.'),
  ('Tek işlemci çekirdeğine sahip bir sistemde döner kilit (spinlock) kullanmak neden ciddi bir performans kaybına yol açar?', 'Kilidi tutan iş parçacığı işlemciyi alamadığı sürece kilit açılamayacağı için zaman dilimi boşa harcanır', ['Tek çekirdekli işlemcilerde atomik bellek komutları donanımsal olarak desteklenmediği için hata verir', 'Spinlock her döngüde sabit diske günlük kaydı yazarak giriş/çıkış darboğazı oluşturduğu için sistemi yavaşlatır', 'Tek çekirdekte döner kilit kullanıldığında işletim sistemi tüm kesmeleri kalıcı olarak kapatmak zorunda kalır'], 'Tek çekirdekte bir iş parçacığı döngüde beklerken kilidi elinde tutan diğer iş parçacığı çalışıp kilidi bırakamaz; zaman dilimi bitene kadar işlemci tamamen boşa döner.'),
  ('Çok çekirdekli bir sistemde ise çok kısa süren (birkaç makine komutu uzunluğunda) bir kritik bölge için uyutan mutex yerine spinlock tercih edilmesinin nedeni nedir?', 'Uyutma ve uyandırma kaynaklı iki bağlam değişimi maliyetinin bekleme süresinden daha yüksek olması', ['Spinlock yapısının paylaşılan önbellek tutarlılığı protokollerini tamamen devre dışı bırakması', 'Uyutan mutex kilitlerinin dört çekirdekten fazla işlemcilerde karşılıklı dışlama sağlayamaması', 'Spinlock kullanıldığında kritik bölge içindeki tüm değişkenlerin otomatik olarak yazmaçlara taşınması'], 'Kritik bölge çok kısaysa diğer çekirdekteki iş parçacığı kilidi hemen bırakacaktır; iş parçacığını uyutup tekrar uyandırmak (iki context switch) çok daha maliyetli olur.'),
  ('Donanım düzeyinde atomik olarak bir bellek adresindeki değeri okuyan, beklenen değerle karşılaştıran ve yalnızca eşitse yeni değeri yazan komut hangisidir?', 'Compare-And-Swap (CAS)', ['Branch-On-Equal (BEQ)', 'Load-Effective-Address (LEA)', 'Move-Zero-Extend (MOVZX)'], 'Compare-And-Swap (CAS), kilitsiz (lock-free) veri yapılarının ve modern kilitlerin temelini oluşturan atomik karşılaştır-ve-değiştir komutudur.'),
  ('Kritik bölge probleminin üç temel çözüm koşulundan biri olan "İlerleme" (Progress) ilkesi neyi garanti altına alır?', 'Kritik bölgede kimse yokken girmek isteyenler arasından seçimin süresiz ertelenmemesini', ['Kritik bölgeye giren her iş parçacığının en fazla bir milisaniye içinde işini bitirmesini', 'Düşük öncelikli iş parçacıklarının hiçbir zaman yüksek önceliklilerden önce seçilmemesini', 'Sistemdeki tüm iş parçacıklarının kritik bölgeye tam olarak eşit sayıda giriş yapmasını'], 'İlerleme (Progress) koşulu, kritik bölge boşken girmek isteyen iş parçacıkları varsa kimin gireceği kararının kritik bölge dışındakilerce engellenememesini ve süresiz geciktirilmemesini şart koşar.'),
  ('Kritik bölge probleminin "Sınırlı Bekleme" (Bounded Waiting) koşulu sağlandığında hangi istenmeyen durum doğrudan önlenmiş olur?', 'Kritik bölgeye girmek isteyen bir iş parçacığının süresiz dışlanması (Açlık / Starvation)', ['Farklı süreçlerin birbirinin özel yığın (stack) alanına izinsiz veri yazması', 'İşlemci önbellek satırlarının çekirdekler arasında yanlış paylaşılması (False sharing)', 'Kullanıcı modundaki bir iş parçacığının doğrudan ayrıcalıklı donanım komutlarını çalıştırması'], 'Sınırlı bekleme, bir iş parçacığı giriş isteği yaptıktan sonra diğerlerinin kritik bölgeye girebileceği sayıyı üstten sınırlayarak açlığı (starvation) engeller.'),
  ('İki iş parçacıklı yazılım tabanlı karşılıklı dışlama çözümü olan Peterson Algoritması hangi iki paylaşılan değişken türüne dayanır?', 'Bir turn (sıra) tamsayısı ve iki elemanlı flag (istek) mantıksal dizisi', ['İki adet sayma semaforu ve bir adet çekirdek düzeyinde mesaj kuyruğu', 'Bir adet donanım kesme maskesi ve iki adet salt okunur yığın işaretçisi', 'Üç boyutlu bir kaynak matrisi ve her iş parçacığı için ayrı zamanlayıcı'], 'Peterson algoritması, hangi iş parçacığının girmek istediğini belirten flag[2] dizisi ile çakışma anında önceliği belirleyen turn değişkenini kullanır.'),
  ('Klasik Peterson Algoritması modern çok çekirdekli işlemcilerde bellek bariyeri (memory barrier) olmadan çalıştırıldığında neden başarısız olabilir?', 'İşlemci veya derleyici bağımsız görünen yazma/okuma işlemlerinin sırasını değiştirebildiği için', ['Modern işlemciler mantıksal (boolean) dizileri ana bellekte tutmayı desteklemediği için', 'Algoritma yalnızca tek sayılı saat frekansına sahip işlemcilerde doğru çalışabildiği için', 'Çok çekirdekli işlemcilerde küresel değişkenler her çekirdek için ayrı kopyalandığı için'], 'Modern mimarilerde komut yeniden sıralama (instruction reordering) ve yazma tamponları nedeniyle flag ve turn güncellemeleri diğer çekirdeğe ters sırada görünebilir; bunu önlemek için bellek bariyeri gerekir.'),
  ('Çok sayıda okuma ve çok seyrek yazma yapılan paylaşılan bir sözlük yapısında yüksek eşzamanlılık sağlamak için hangi kilit türü en uygundur?', 'Okuyucu-Yazıcı Kilidi (Read-Write Lock)', ['Özyinelemeli Mutex (Recursive Mutex)', 'İkili Semafor (Binary Semaphore)', 'Tekil Döner Kilit (Spinlock)'], 'Okuyucu-yazıcı kilidi, yazıcı yokken birden çok okuyucunun aynı anda veriyi okumasına izin verirken yazma anında tam dışlama sağlayarak okuma ağırlıklı yüklerde performansı artırır.'),
  ('Aynı iş parçacığının zaten elinde tuttuğu bir kilidi kendisini bloke etmeden birden fazla kez kilitleyebilmesine olanak tanıyan kilit türü hangisidir?', 'Özyinelemeli kilit (Recursive / Reentrant mutex)', ['Engelsiz kilit (Wait-free lock)', 'İyimser kilit (Optimistic lock)', 'Kuyruklu döner kilit (Ticket spinlock)'], 'Özyinelemeli (reentrant) mutex, kilidin sahibini ve kilitlenme sayısını takip ederek aynı iş parçacığının iç içe fonksiyon çağrılarında kendi kendini kilitlemesini önler.'),
  ('Bir özyinelemeli (reentrant) mutex aynı iş parçacığı tarafından iç içe 4 kez kilitlenmişse diğer iş parçacıklarının bu kilidi alabilmesi için kaç kez unlock çağrılmalıdır?', '4', ['1', '3', '2'], 'Özyinelemeli kilit her lock işleminde iç sayacını bir artırır; kilidin tamamen serbest kalması için sayaç sıfırlanana dek tam 4 kez unlock çağrılması gerekir.'),
  ('Çoğa-Bir (Many-to-One) iş parçacığı modelinde (birden çok kullanıcı iş parçacığının tek çekirdek iş parçacığına eşlenmesi) en büyük dezavantaj nedir?', 'Bir iş parçacığı engelleyici sistem çağrısı yaptığında süreçteki tüm iş parçacıklarının durması', ['Her iş parçacığı oluşturulduğunda çekirdek belleğinde devasa sayfa tabloları ayrılması', 'Aynı süreçteki iş parçacıklarının küresel değişkenleri hiçbir şekilde paylaşamaması', 'Bağlam değişimi için her seferinde donanım kesmesi ve çekirdek geçişi gerekmesi'], 'Çekirdek yalnızca tek bir yürütme birimi gördüğünden, kullanıcı iş parçacıklarından biri blokeli I/O çağrısı yaparsa tüm süreç bloke olur ve çok çekirdekten yararlanılamaz.'),
  ('Programlama dillerinde bir değişkenin volatile olarak işaretlenmesi (örneğin C/C++ dilinde) eşzamanlılık açısından neyi sağlar ve neyi sağlayamaz?', 'Derleyicinin değişkeni yazmaçta önbelleklemesini önler ama bileşik işlemleri atomik yapmaz', ['Tüm aritmetik işlemleri donanım düzeyinde atomik yapar ama önbellek tutarlılığını bozar', 'Kritik bölgeye otomatik mutex ekler ama bellek sızıntılarını engellemekte yetersiz kalır', 'Değişkeni tüm iş parçacıkları için yerel yığına kopyalar ama okuma hızını yarıya düşürür'], 'C/C++\'ta volatile, derleyicinin bellek okumalarını/yazmalarını optimize edip atlamasını engeller ancak x++ gibi işlemlerde atomiklik veya bellek bariyeri garantisi vermez.'),
  ('Üretici-Tüketici (Producer-Consumer) probleminde boyutu N olan sınırlı bir tampon için kullanılan empty ve full sayma semaforlarının başlangıç değerleri ne olmalıdır?', 'empty = N, full = 0', ['empty = 0, full = N', 'empty = N, full = N', 'empty = 1, full = 0'], 'Başlangıçta tampon tamamen boş olduğu için boş yuva sayısını tutan empty semaforu N, dolu yuva sayısını tutan full semaforu ise 0 değerinden başlar.'),
  ('Sınırlı tamponlu Üretici-Tüketici probleminde empty ve full semaforlarına ek olarak neden bir de mutex (veya ikili semafor) kullanılır?', 'Birden çok üretici veya tüketicinin tampon indekslerini aynı anda değiştirip veri ezmesini önlemek için', ['Tampon tamamen dolduğunda üreticilerin işlemci hızını donanımsal olarak düşürmek için', 'Tüketici iş parçacığının boş tampondan veri okumasını tek başına engellemek için', 'İşletim sisteminin tampon belleğini sabit diske takaslamasını (swapping) yasaklamak için'], 'empty ve full taşmayı ve boş okumayı önlerken, mutex tamponun iç veri yapısına ve eklenecek/çıkarılacak indis değişkenlerine eşzamanlı erişimde yarış durumunu engeller.'),
  ('Bir durum değişkeni (condition variable) üzerinde wait() çağrıldığında arka planda atomik olarak hangi iki adım gerçekleşir?', 'İlişkili mutex kilidi serbest bırakılır ve iş parçacığı uyku kuyruğuna alınır', ['Mutex kilidi iki kez kilitlenir ve diğer tüm iş parçacıklarına kesme gönderilir', 'Paylaşılan bellek sıfırlanır ve iş parçacığının önceliği en üst düzeye çıkarılır', 'İş parçacığı yeni bir süreç oluşturur ve mevcut yığın alanını diske yazar'], 'Durum değişkeninde wait(), kayıp uyandırma (lost wakeup) sorununu önlemek için ilişkili kilidi bırakma ve uyku durumuna geçme işlemlerini tek bir atomik adımda yapar.'),
  ('Durum değişkeni (condition variable) kullanan bir iş parçacığının koşulu if yerine while döngüsü içinde kontrol etmesinin temel nedeni nedir?', 'Sahte uyanmalar (spurious wakeups) veya uyanana kadar başka bir iş parçacığının koşulu bozabilmesi', ['Derleyicilerin durum değişkenlerini if blokları içinde sözdizimsel olarak kabul etmemesi', 'while döngüsünün donanım düzeyinde otomatik olarak tüm önbellekleri temizlemesi', 'if kullanıldığında signal gönderen iş parçacığının anında sonlandırılması'], 'İş parçacığı uyandırılıp kilidi tekrar alana kadar başka bir iş parçacığı araya girip koşulu değiştirmiş olabilir ya da işletim sistemi kaynaklı sahte uyanma (spurious wakeup) yaşanabilir.'),
  ('Donanım düzeyinde bir bellek konumunu atomik olarak okuyup aynı anda oraya 1 (true) yazarak eski değeri döndüren senkronizasyon komutu hangisidir?', 'Test-And-Set (TAS)', ['Fetch-And-Clear (FAC)', 'Jump-And-Link (JAL)', 'Push-All-Registers (PUSHA)'], 'Test-And-Set, bellek hücresindeki mevcut değeri döndürüp hücreyi atomik olarak 1\'e ayarlayarak basit kilit mekanizmaları kurmayı sağlar.'),
  ('Başlangıçta paylaşılan bakiye = 1000 TL iken T1 iş parçacığı 200 TL yatırma, T2 iş parçacığı 300 TL çekme işlemini kilitsiz yapmaktadır; ikisi de aynı anda 1000 okuyup önce T1 sonra T2 sonucu yazarsa son bakiye kaç olur?', '700', ['900', '1200', '500'], 'Her iki iş parçacığı da 1000 değerini okur; T1 belleğe 1200 yazar, hemen ardından T2 kendi okuduğu 1000 üzerinden hesapladığı 700 değerini yazarak T1\'in güncellemesini ezer (kayıp güncelleme).'),
  ('N adet iş parçacığının tümü belirli bir hesaplama aşamasına ulaşmadan hiçbirinin bir sonraki aşamaya geçmemesini sağlayan senkronizasyon aracı hangisidir?', 'Bariyer (Barrier)', ['Özyinelemeli kilit (Recursive lock)', 'İkili semafor (Binary semaphore)', 'Mesaj kutusu (Mailbox)'], 'Bariyer senkronizasyonu, katılımcı tüm iş parçacıkları buluşma noktasına varana kadar erken gelenleri bekletir ve sonuncu geldiğinde hepsini birlikte serbest bırakır.'),
  ('Bir fonksiyonun birden çok iş parçacığı tarafından aynı anda güvenle çağrılabilmesi (thread-safe olması) için aşağıdakilerden hangisinden kaçınılmalıdır?', 'Korunmasız statik veya küresel değişkenleri değiştirmekten', ['Fonksiyon içinde yalnızca yığında (stack) tutulan yerel değişkenler tanımlamaktan', 'Salt okunur sabit (const) tablolardan değer sorgulamaktan', 'Parametreleri değer ile (pass-by-value) alıp sonucu döndürmekten'], 'Korunmasız statik veya küresel değişkenler tüm iş parçacıkları arasında paylaşıldığından eşzamanlı çağrılarda yarış durumuna yol açar ve fonksiyonun iş parçacığı güvenliğini bozar.'),
  ('İş parçacığına özgü depolama (Thread-Local Storage - TLS) mekanizmasının kullanım amacı nedir?', 'Küresel kapsamda tanımlanan bir değişkenin her iş parçacığı için ayrı ve bağımsız bir kopyasını tutmak', ['Tüm iş parçacıklarının yerel yığınlarını tek bir ortak bellek havuzunda birleştirmek', 'Süreçler arasında ağ üzerinden şifreli semafor değerleri aktarmak', 'Kritik bölge içindeki kodları işletim sistemi çekirdeğine kalıcı olarak taşımak'], 'TLS (Thread-Local Storage), sözdizimsel olarak küresel görünen bir değişkenin her iş parçacığına özel ayrı bir örneğinin bulunmasını sağlayarak kilit ihtiyacını ortadan kaldırır.'),
  ('Bir grafik arayüz (GUI) uygulamasında ağdan büyük bir dosya indirme işleminin doğrudan ana arayüz iş parçacığında (UI thread) senkron yapılması hangi soruna yol açar?', 'İndirme bitene kadar arayüzün donması ve kullanıcı tıklamalarına yanıt verememesi', ['Dosya verilerinin diğer süreçlerin adres alanlarıyla kendiliğinden karışması', 'İşlemcinin aritmetik mantık biriminin (ALU) kalıcı olarak kilitlenmesi', 'Uygulamanın kullandığı tüm dinamik kütüphanelerin bellekten silinmesi'], 'Arayüz olay döngüsü (event loop) tek bir UI iş parçacığında çalıştığından, uzun süren blokeli işlemler bu iş parçacığını meşgul ederek ekran güncellemelerini ve girdi işlemeyi durdurur.'),
  ('İki iş parçacığı (T1 ve T2) arasında T1\'in ürettiği hazirla() çıktısı bitmeden T2\'nin kullan() işlevini çalıştırmaması için başlangıç değeri ne olan bir semafor nasıl kullanılmalıdır?', 'Başlangıç değeri 0 olan semaforda T1 hazirla() sonrası signal, T2 kullan() öncesi wait çağırır', ['Başlangıç değeri 1 olan semaforda T1 hazirla() öncesi wait, T2 kullan() sonrası signal çağırır', 'Başlangıç değeri 2 olan semaforda her iki iş parçacığı da işlevlerinden önce wait çağırır', 'Başlangıç değeri 0 olan semaforda T1 hazirla() öncesi wait, T2 kullan() sonrası signal çağırır'], 'Sıralama (rendezvous/ordering) için semafor 0\'dan başlatılır; T2 erken gelirse wait ile bekler, T1 işini bitirip signal çağırdığında T2 ilerler.'),
  ('Düşük öncelikli bir iş parçacığının elinde tuttuğu kilidi yüksek öncelikli bir iş parçacığı beklerken, orta öncelikli üçüncü bir iş parçacığının işlemciyi alarak düşük öncelikliyi çalıştırmamasına ne denir?', 'Öncelik evrilmesi (Priority inversion)', ['Konvoy etkisi (Convoy effect)', 'Yanlış paylaşım (False sharing)', 'Bellek parçalanması (Memory fragmentation)'], 'Orta öncelikli iş parçacığının düşük öncelikli kilit sahibini kesmesiyle yüksek öncelikli iş parçacığının dolaylı olarak bekletilmesine öncelik evrilmesi (priority inversion) denir.'),
  ('Öncelik evrilmesi (priority inversion) sorununu çözmek için kullanılan "Öncelik Mirası" (Priority Inheritance) protokolü nasıl çalışır?', 'Kilidi tutan düşük öncelikli iş parçacığının önceliğini geçici olarak kilidi bekleyen en yüksek öncelikliye yükseltir', ['Kilidi bekleyen yüksek öncelikli iş parçacığını iptal edip kilidi orta öncelikli iş parçacığına devreder', 'Sistemdeki tüm iş parçacıklarının önceliklerini süreç sonlanana kadar en düşük seviyeye sabitler', 'Düşük öncelikli iş parçacığının kritik bölgesini tamamlamadan kilidini zorla elinden alır'], 'Öncelik mirası protokolünde düşük öncelikli kilit sahibi, kendisini bekleyen yüksek öncelikli iş parçacığının önceliğini geçici olarak devralır; böylece orta öncelikliler araya giremez ve kilit hızla bırakılır.'),
  ('Çok çekirdekli işlemcilerde iki farklı iş parçacığının birbirinden tamamen bağımsız iki değişkene yazma yapmasına rağmen aynı önbellek satırında (cache line) bulunmaları yüzünden yavaşlamasına ne denir?', 'Yanlış paylaşım (False sharing)', ['Yarış durumu (Race condition)', 'Kayıp güncelleme (Lost update)', 'Kilit sızıntısı (Lock leakage)'], 'Farklı değişkenler aynı önbellek satırını (örneğin 64 bayt) paylaştığında önbellek tutarlılığı protokolü satırı çekirdekler arasında sürekli geçersiz kılar; buna yanlış paylaşım (false sharing) denir.'),
  ('Yanlış paylaşım (false sharing) kaynaklı performans düşüşünü engellemek için yazılımcılar genellikle hangi tekniği uygular?', 'Değişkenler arasına dolgu baytları (padding) ekleyerek farklı önbellek satırlarına hizalamak', ['Bağımsız değişkenlerin tamamını tek bir küresel mutex kilidi altında toplamak', 'İş parçacığı sayısını işlemci çekirdeği sayısının tam on katına çıkarmak', 'Tüm yerel değişkenleri sabit disk üzerindeki sanal bellek dosyasında tutmak'], 'Değişkenleri önbellek satırı boyutuna (genellikle 64 bayt) hizalayacak şekilde dolgu (padding) ile ayırmak, her çekirdeğin kendi önbellek satırında çakışmasız çalışmasını sağlar.'),
  ('Kaba taneli kilitleme (coarse-grained locking) ile ince taneli kilitleme (fine-grained locking) karşılaştırıldığında hangisi doğrudur?', 'İnce taneli kilitleme eşzamanlılığı artırır ancak uygulama karmaşıklığını ve kilitlenme riskini yükseltir', ['Kaba taneli kilitleme her zaman daha yüksek paralel hızlanma sağlar ve hiç bellek kullanmaz', 'İnce taneli kilitlemede tüm veri yapısı için yalnızca tek bir küresel kilit kullanılır', 'Kaba taneli kilitlemede birden fazla kilit sırayla alındığı için kilitlenme riski çok daha fazladır'], 'Kaba taneli kilitleme tek kilitle basitlik sağlarken darboğaz yaratır; ince taneli kilitleme veri yapısını küçük parçalar halinde kilitleyerek paralelliği artırır fakat tasarım ve kilit sırası yönetimini zorlaştırır.'),
  ('Bir iş parçacığı havuzu (thread pool) kullanmanın her gelen görev için sıfırdan yeni iş parçacığı oluşturup yok etmeye göre temel avantajı nedir?', 'İş parçacığı yaratma/sonlandırma maliyetini ortadan kaldırmak ve kaynak tüketimini sınırlamak', ['Paylaşılan değişkenlerde yarış durumu oluşma ihtimalini matematiksel olarak sıfırlamak', 'Tek çekirdekli bir işlemciyi donanımsal olarak çok çekirdekli işlemciye dönüştürmek', 'Kritik bölgelerde atomik komutlara ve kilitlere olan ihtiyacı tamamen kaldırmak'], 'İş parçacığı havuzu, hazır bekleyen işçi iş parçacıklarını yeniden kullanarak sürekli oluşturma/yıkma yükünü önler ve aşırı iş parçacığı sayısından doğacak bellek/çizelgeleme çöküşünü engeller.'),
  ('UNIX/POSIX tabanlı bir sistemde fork() sistem çağrısı çok iş parçacıklı bir süreç içinde çağrıldığında yeni oluşan çocuk süreçte standart olarak kaç iş parçacığı bulunur?', 'Yalnızca fork() çağrısını yapan iş parçacığının kopyası olan 1 iş parçacığı', ['Ebeveyn süreçteki tüm iş parçacıklarının ikişer kopyası', 'Hiçbir iş parçacığı bulunmaz, yalnızca boş adres uzayı oluşur', 'Sistemdeki toplam fiziksel çekirdek sayısı kadar iş parçacığı'], 'POSIX standardına göre çok iş parçacıklı bir süreçte fork() çağrıldığında çocuk süreçte yalnızca fork() çağrısını gerçekleştiren iş parçacığı kopyalanır.'),
  ('Çok iş parçacıklı bir süreçte başka bir iş parçacığı bir mutex kilidini tutarken fork() çağrılır ve çocuk süreç exec() yapmadan aynı kilidi almaya çalışırsa ne olur?', 'Kilidi tutan iş parçacığı çocuk sürece kopyalanmadığı için çocuk süreç kilidi asla alamaz ve takılır', ['Çocuk süreç tüm kilitleri otomatik olarak açık (unlocked) durumda devralır ve hemen girer', 'Ebeveyn süreçteki iş parçacığı çocuk sürecin belleğine uzaktan erişerek kilidi açar', 'İşletim sistemi fork() anında kilitli olan tüm bellek sayfalarını sıfırlayarak hatayı önler'], 'Çocuk süreç belleğin o anki kopyasını (kilitli mutex durumunu) devralır ancak kilidi açacak olan diğer iş parçacığı çocuk sürece kopyalanmadığı için çocuk süreç o kilidi beklerken sonsuza dek kilitlenir.'),
  ('Sanal adres uzunluğu 32 bit ve sayfa boyutu 4 KB (2^12 bayt) olan bir sistemde, sanal sayfa numarası (VPN) kaç bitten oluşur?', '20 bit', ['12 bit', '16 bit', '24 bit'], '4 KB sayfa boyutu için 12 bit offset gerekir; 32 bitlik sanal adresten 12 bit çıkarıldığında VPN için 20 bit kalır.'),
  ('Sayfa boyutu 8 KB olan ve bayt düzeyinde adreslenen bir bilgisayar mimarisinde sayfa içi göreli konum (offset) alanı kaç bittir?', '13 bit', ['11 bit', '12 bit', '14 bit'], '8 KB = 8 * 1024 = 8192 = 2^13 bayt olduğundan sayfa içindeki her baytı tekil adreslemek için 13 bit gerekir.'),
  ('16 bit sanal adres kullanan ve sayfa boyutu 1 KB olan bir sistemde, bir sürecin adresleyebileceği en fazla sanal sayfa sayısı kaçtır?', '64', ['16', '32', '128'], '16 bit adres alanı 2^16 bayttır ve sayfa boyutu 2^10 bayttır; 2^16 / 2^10 = 2^6 = 64 sanal sayfa bulunur.'),
  ('Bir bellek erişimi sırasında aranan sanal sayfa numarası TLB\'de bulunamadığında (TLB miss) donanım veya işletim sistemi ilk olarak ne yapar?', 'Ana bellekteki sayfa tablosuna başvurarak geçerli eşleşmeyi arar', ['Sabit diskten ilgili sayfayı doğrudan fiziksel belleğe yükler', 'Çalışmakta olan süreci sonlandırarak bellek koruma hatası üretir', 'İşlemci önbelleğindeki tüm veri satırlarını geçersiz kılar'], 'TLB ıskası sayfanın RAM\'de olmadığı anlamına gelmez; yalnızca çevrimin TLB\'de olmadığını gösterir, bu yüzden önce RAM\'deki sayfa tablosuna bakılır.'),
  ('TLB erişim süresinin 2 ns, ana bellek erişim süresinin 100 ns olduğu tek seviyeli sayfalamalı bir sistemde TLB isabet oranı %90 ise etkin bellek erişim süresi (EMAT) kaç ns olur?', '112 ns', ['102 ns', '110 ns', '120 ns'], 'İsabette 2 + 100 = 102 ns, ıskada 2 + 100 (sayfa tablosu) + 100 (veri) = 202 ns sürer; 0,9 * 102 + 0,1 * 202 = 91,8 + 20,2 = 112 ns bulunur.'),
  ('Sayfa tablosu girdisindeki "kirli bit" (dirty/modified bit) hangi amaçla kullanılır?', 'Sayfa RAM\'den çıkarılırken diske geri yazılıp yazılmayacağını belirlemek', ['Sayfanın TLB içinde ne kadar süreyle saklanacağını hesaplamak', 'Kullanıcı kipindeki süreçlerin çekirdek belleğine erişimini engellemek', 'Boru hattındaki yanlış dallanma tahminlerini geri sarmak'], 'RAM\'deki sayfaya yazma yapıldığında kirli bit 1 olur; sayfa kurban seçildiğinde bit 0 ise diske tekrar yazmaya gerek kalmaz, G/Ç tasarrufu sağlanır.'),
  ('Sayfalama sistemlerinde "iç parçalanma" (internal fragmentation) en çok sayfanın hangi bölümünde meydana gelir?', 'Bir sürecin bellek alanının son sayfasının kullanılmayan kısmında', ['Fiziksel bellekteki iki dolu çerçeve arasında kalan boş çerçevelerde', 'Sayfa tablosunun TLB\'ye sığmayan üst seviye dizin girdilerinde', 'Disk üzerindeki takas (swap) alanının önyükleme sektöründe'], 'Bellek süreçlere tam sayfa katları halinde verildiği için sürecin son sayfası genellikle tam dolmaz ve kalan baytlar iç parçalanma oluşturur.'),
  ('Saf sayfalama (pure paging) kullanılan bir bellek yönetiminde "dış parçalanma" (external fragmentation) görülmemesinin nedeni nedir?', 'Herhangi bir boş fiziksel çerçevenin herhangi bir sanal sayfaya atanabilmesi', ['Tüm süreçlerin sanal adres alanlarının ardışık fiziksel çerçevelere yerleştirilmesi', 'Sayfa boyutlarının sürecin büyüklüğüne göre çalışma zamanında dinamik küçülmesi', 'İşletim sisteminin her bellek erişiminde RAM\'i sıkıştırarak birleştirmesi'], 'Çerçeveler ve sayfalar eşit ve sabit boyutlu olduğundan, fiziksel bellekte dağınık duran boş çerçeveler bile bitişik sanal sayfalara sorunsuz eşlenebilir.'),
  ('Bağlam anahtarlama (context switch) sırasında adres uzayı tanımlayıcısı (ASID / PCID) desteklemeyen bir işlemcide TLB içeriğine ne yapılmalıdır?', 'Yeni sürecin eski sürecin fiziksel sayfalarına erişmemesi için TLB temizlenmelidir', ['TLB içindeki tüm girdiler sabit diskteki takas alanına yedeklenmelidir', 'TLB girdilerinin yalnızca kirli bitleri sıfırlanarak geçerlilikleri korunmalıdır', 'TLB boyutu iki katına çıkarılarak her iki sürecin tabloları birleştirilmelidir'], 'ASID yoksa TLB hangi çevrimin hangi sürece ait olduğunu ayırt edemez; bellek izolasyonu için bağlam değişiminde TLB boşaltılır.'),
  ('İşletim sistemlerinde fork() çağrısı sonrasında ebeveyn ve çocuk süreçlerin fiziksel sayfaları başlangıçta salt okunur paylaşması ve yalnızca yazma yapıldığında kopyalaması tekniği nedir?', 'Yazmada Kopyalama (Copy-on-Write)', ['İstek Üzerine Sayfalama (Demand Paging)', 'Önceden Getirme (Prefetching)', 'Sayfa Renklendirme (Page Coloring)'], 'Copy-on-Write (CoW), süreç oluşturma anında tüm belleği kopyalamak yerine sayfaları ortak kullandırır; yazma istisnası olduğunda sadece ilgili sayfayı çoğaltır.'),
  ('Sayfa hatası olmayan bellek erişiminin 200 ns, sayfa hatası işleme süresinin 8 ms (8.000.000 ns) olduğu bir sistemde sayfa hatası oranı 10^-6 (milyonda bir) ise etkin erişim süresi kaç ns\'dir?', '208 ns', ['280 ns', '1000 ns', '8200 ns'], 'EMAT = (1 - 10^-6) * 200 + (10^-6) * 8.000.000 ≈ 200 + 8 = 208 ns olur; çok düşük hata oranı bile süreyi hissedilir etkiler.'),
  ('Gelecekte en uzun süre boyunca erişilmeyecek olan sayfayı kurban seçerek kuramsal olarak en az sayfa hatasını üreten, ancak pratikte doğrudan uygulanamayan algoritma hangisidir?', 'Optimal (MIN / Belady) sayfa değiştirme algoritması', ['İkinci Şans (Second Chance) sayfa değiştirme algoritması', 'En Az Sıklıkla Kullanılan (LFU) sayfa değiştirme algoritması', 'Yaşlandırma (Aging) tabanlı sayfa değiştirme algoritması'], 'Optimal algoritma gelecekteki bellek referans dizisini önceden bilmeyi gerektirdiği için gerçek işletim sistemlerinde yalnızca kıyaslama ölçütü olarak kullanılır.'),
  ('3 fiziksel çerçeveye sahip başlangıçta boş bir bellekte 1, 2, 3, 4, 1, 2 sayfa referans dizisi LRU algoritması ile işlenirse toplam kaç sayfa hatası oluşur?', '6', ['4', '5', '3'], '1, 2, 3 yerleşir (3 hata); 4 geldiğinde en eski erişilen 1 çıkar (4. hata: [2,3,4]); 1 geldiğinde 2 çıkar (5. hata: [3,4,1]); 2 geldiğinde 3 çıkar (6. hata).'),
  ('Bir sayfa değiştirme algoritmasında bir sürece ayrılan fiziksel çerçeve sayısı artırılmasına rağmen sayfa hatası sayısının artması olgusuna ne ad verilir?', 'Belady anomalisi', ['Amdahl yasası', 'Öncelik tersinmesi', 'Konvoy etkisi'], 'Belady anomalisi, FIFO gibi yığın (stack) özelliğine sahip olmayan algoritmalarda daha fazla RAM çerçevesi verildiğinde sayfa hatasının artabilmesi durumudur.'),
  ('Tam LRU algoritmasını donanımda her bellek erişiminde zaman damgası veya bağlı liste güncelleyerek uygulamak maliyetli olduğundan işletim sistemleri genellikle hangi приблиik (yaklaşık) yöntemi kullanır?', 'Başvuru bitini (reference bit) kullanan Saat (Clock / İkinci Şans) algoritmasını', ['Gelecekteki tüm komutları önceden tarayan Optimal Belady algoritmasını', 'Yalnızca sayfa numaralarının tek veya çift olmasına bakan rastgele seçimi', 'Fiziksel çerçeveleri süreç kimliğine göre sıralayan Doğrusal Arama yöntemini'], 'Saat (Clock) algoritması, MMU\'nun her erişimde 1 yaptığı başvuru bitini dairesel listede kontrol ederek düşük maliyetle LRU\'ya yakın başarım sağlar.'),
  ('Çırpınma (thrashing) yaşayan bir işletim sisteminde çoklu programlama derecesi (aynı anda bellekte tutulan süreç sayısı) yanlışlıkla daha da artırılırsa ne gözlemlenir?', 'Sayfa hatası kuyruğu uzadığı için işlemci (CPU) kullanım oranı daha da düşer', ['Daha fazla süreç hazır kuyruğuna gireceği için işlemci kullanımı %100\'e ulaşır', 'TLB isabet oranı yükselerek disk üzerindeki takas alanı trafiği azalır', 'Sayfa tabloları otomatik birleşerek iç parçalanma tamamen ortadan kalkar'], 'Klasik işletim sistemi yanılgısında düşük CPU kullanımını gören zamanlayıcı yeni süreç eklerse süreç başına düşen çerçeve iyice azalır ve çırpınma şiddetlenir.'),
  ('Peter Denning tarafından geliştirilen ve bir sürecin belirli bir zaman penceresi (Δ) içinde aktif olarak başvurduğu sayfalar kümesini tanımlayan model hangisidir?', 'Çalışma kümesi (working set) modeli', ['Bankacı (banker\'s) kaynak ayırma modeli', 'Üretici-tüketici senkronizasyon modeli', 'Yemek yiyen filozoflar modeli'], 'Çalışma kümesi modeli, her sürece en az aktif çalışma kümesi büyüklüğü kadar fiziksel çerçeve ayrılarak çırpınmanın önlenmesini hedefler.'),
  ('İşlemci önbelleklerinin ana bellekten tek bir bayt yerine 64 baytlık bir "önbellek satırı" (cache line / block) halinde veri çekmesi hangi ilkeden yararlanmak için tasarlanmıştır?', 'Uzamsal yerellik', ['Zamansal yerellik', 'Sanal sayfa renklendirme', 'Yazmaç penceresi kaydırma'], 'Aranan baytın yanındaki komşu baytların da aynı önbellek satırıyla birlikte getirilmesi, ardışık erişimlerde zorunlu ıskaları büyük ölçüde azaltır.'),
  ('C, C++ ve Python (NumPy varsayılanı) gibi dillerde iki boyutlu bir A[M][N] matrisi bellekte hangi düzende ardışık olarak saklanır?', 'Satır-öncelikli (row-major) düzende', ['Sütun-öncelikli (column-major) düzende', 'Köşegen-öncelikli (diagonal-major) düzende', 'Ters ikili ağaç (heap) düzeninde'], 'Satır-öncelikli düzende önce 0. satırın tüm elemanları (A[0][0], A[0][1], ...), hemen ardından 1. satırın elemanları bellekte yan yana dizilir.'),
  ('Bellekte satır-öncelikli (row-major) tutulan büyük bir A[4096][4096] matrisini tararken dış döngünün satırları (i), iç döngünün sütunları (j) gezerek A[i][j] okuması neden A[j][i] okumasından çok daha hızlıdır?', 'Bellekte yan yana duran elemanları sırayla okuyarak önbellek satırı ve TLB isabet oranını en üst düzeye çıkardığı için', ['İşlemcinin çarpma ve toplama birimlerini devre dışı bırakarak yalnızca bit kaydırma işlemi yaptığı için', 'Derleyicinin iç döngüdeki tüm dizi erişimlerini otomatik olarak sabit diskteki takas alanına yönlendirdiği için', 'Sütun indeksinin tek sayı olduğu durumlarda bellek yönetim biriminin adres çevrimini tamamen atladığı için'], 'A[i][j] erişimi adım boyunu (stride) 1 eleman yaparak bir önbellek satırındaki tüm elemanları ıskasız kullanır; A[j][i] ise her adımda satır atlayarak sürekli önbellek ve TLB ıskası üretir.'),
  ('Büyük matris çarpımı algoritmalarında döngülerin küçük alt matrislere bölünerek işlenmesi tekniği (loop tiling / blocking) neyi amaçlar?', 'Alt matris verilerini önbellekten atılmadan önce tekrar tekrar kullanarak zamansal yerelliği artırmayı', ['Sanal adres uzunluğunu 64 bitten 32 bite düşürerek sayfa tablosunu küçültmeyi', 'İşlemci saat frekansını düşürerek boru hattı aşamalarının sayısını azaltmayı', 'Sabit disk üzerindeki sektör boyutunu önbellek satırı boyutuyla eşitlemeyi'], 'Tiling (bloklama), önbelleğe sığacak büyüklükteki alt bloklar üzerinde tüm çarpım-toplam işlemlerini tamamlayarak ana bellek trafiğini çarpıcı biçimde azaltır.'),
  ('Toplam önbellekte boş yer bulunmasına rağmen, doğrudan eşlemeli (direct-mapped) veya küme ilişkisel önbellekte birden fazla aktif adresin aynı önbellek kümesine eşlenmesi sonucu oluşan ıska türü hangisidir?', 'Çakışma (conflict) ıskası', ['Zorunlu (compulsory) ıska', 'Kapasite (capacity) ıskası', 'Yetki (protection) ıskası'], 'Tam ilişkisel olmayan önbelleklerde aynı indeks bitlerine sahip adresler aynı küme için yarışır ve birbirlerini erken tahliye ederek çakışma ıskası doğurur.'),
  ('Bir önbelleğin ilişkisellik derecesi (associativity, örneğin doğrudan eşlemeliden 8-yollu küme ilişkisele) artırıldığında hangi değişim beklenir?', 'Çakışma ıskaları azalırken etiket (tag) karşılaştırma donanımı ve erişim gecikmesi biraz artar', ['Zorunlu (soğuk) ıskalar tamamen sıfırlanırken önbellek satır boyutu yarıya düşer', 'Kapasite ıskaları artarken ana bellek veri yolu bant genişliği iki katına çıkar', 'Sayfa boyutu büyürken sanal bellek adres uzayı 32 bit ile sınırlandırılır'], 'Daha fazla yol (way), aynı kümeye düşen bloklara esneklik sağlayarak çakışma ıskalarını azaltır; ancak paralel karşılaştırıcı sayısı arttığı için güç ve gecikme maliyeti eklenir.'),
  ('Boru hattı olmayan tek çevrimli bir işlemcide bir komut 800 ps sürerken, bu işlemci her aşaması 200 ps süren dengeli 5 aşamalı boru hattına dönüştürülürse ideal durumda (tehlikesiz, çok sayıda komut için) hızlanma (speedup) yaklaşık kaç kat olur?', '4 kat', ['5 kat', '2,5 kat', '8 kat'], 'Boru hatsız tamamlama hızı her 800 ps\'de 1 komuttur; 5 aşamalı hatta saat periyodu 200 ps olduğundan kararlı durumda her 200 ps\'de 1 komut biter: 800 / 200 = 4 kat hızlanma sağlanır.'),
  ('Aşama gecikmeleri sırasıyla 150 ps, 200 ps, 250 ps, 200 ps ve 150 ps olan 5 aşamalı bir boru hattında (boru hattı yazmaç gecikmesi 20 ps ise) ulaşılabilir en kısa saat periyodu kaç ps\'dir?', '270 ps', ['210 ps', '950 ps', '970 ps'], 'Boru hattında saat periyodu en yavaş (darboğaz) aşama tarafından belirlenir: max(150, 200, 250, 200, 150) + 20 ps yazmaç yükü = 270 ps olur.'),
  ('5 aşamalı ideal (hiç duraklama olmayan) bir boru hattında art arda gelen 100 makine komutunun tamamlanması toplam kaç saat çevrimi (clock cycle) sürer?', '104 çevrim', ['100 çevrim', '500 çevrim', '105 çevrim'], 'k aşamalı boru hattında n komut için toplam çevrim sayısı k + (n - 1) formülüyle hesaplanır: 5 + (100 - 1) = 104 çevrimdir.'),
  ('Harvard önbellek mimarisinde L1 seviyesinde buyruk önbelleği (I-cache) ve veri önbelleğinin (D-cache) birbirinden ayrı tasarlanmasının boru hattına sağladığı doğrudan yarar nedir?', 'IF aşamasındaki komut getirme ile MEM aşamasındaki veri erişimi arasındaki yapısal tehlikeyi önlemek', ['Koşullu dallanma komutlarının yönünü derleme zamanında %100 doğrulukla belirlemek', 'RAW (yazmadan sonra okuma) veri bağımlılıklarını yönlendirme olmadan çözmek', 'Sanal adres çevriminde kullanılan sayfa tablosu boyutunu yarıya indirmek'], 'Aynı çevrimde bir komut IF aşamasında buyruk okurken daha önceki bir yükleme/saklama komutu MEM aşamasında veri okuyup yazabilir; ayrı L1 önbellekler bu çakışmayı önler.'),
  ('Boru hattında ADD R1, R2, R3 komutunun hemen ardından gelen SUB R4, R1, R5 komutunun duraklama (stall) yaşamadan çalışmasını sağlayan donanım tekniği hangisidir?', 'Veri yönlendirme / baypas (forwarding / bypassing)', ['Dallanma hedef önbelleği (branch target buffer)', 'İstek üzerine sayfalama (demand paging)', 'Çoklu iş parçacığı bağlam anahtarlama'], 'Yönlendirme (forwarding), ADD komutunun EX aşaması sonunda ALU çıkışında oluşan R1 değerini WB aşamasını beklemeden doğrudan SUB komutunun ALU girişine aktarır.'),
  ('Derleyicinin (compiler) load-use veri tehlikesi nedeniyle oluşacak 1 çevrimlik boş beklemeyi önlemek için kodun anlamını bozmadan araya bağımsız başka bir komut yerleştirmesi tekniğine ne denir?', 'Komut zamanlama / yeniden sıralama (instruction scheduling)', ['Yazmaç taşması (register spilling)', 'Döngü birleştirme (loop fusion)', 'Sanal bellek sıkıştırma (memory compaction)'], 'Derleyici bağımsız bir komutu yükleme ile kullanım arasına taşıyarak boru hattındaki kabarcığı (NOP/stall) faydalı işle doldurur.'),
  ('İşlemcinin bir dallanma tahmini yanlış çıktığında (branch misprediction), yanlış yoldan boru hattına alınmış olan komutlara ne yapılır?', 'Mimari durumu değiştirmemeleri için boru hattından temizlenir', ['Yürütmeleri tamamlanıp sonuçları kalıcı olarak ana belleğe yazılır', 'Sabit diskteki takas alanına taşınarak sonraki döngü için saklanır', 'Kesme vektör tablosuna kaydedilerek işletim sistemi çekirdeğine devredilir'], 'Yanlış spekülatif yoldaki komutlar yazmaç dosyasını veya belleği bozmamalıdır; bu nedenle etkisizleştirilip (kabarcığa dönüştürülüp) doğru adresten getirme başlatılır.'),
  ('Komutların %20\'sinin koşullu dallanma olduğu, dallanma tahmin doğruluğunun %90 ve yanlış tahmin cezasının (misprediction penalty) 15 çevrim olduğu, diğer tüm komutlarda duraklama yaşanmayan bir işlemcide ortalama CPI (komut başına çevrim) kaçtır?', '1,30', ['1,15', '1,20', '2,50'], 'Temel CPI = 1\'dir; komut başına ek ceza = dallanma oranı * yanlış tahmin oranı * ceza = 0,20 * (1 - 0,90) * 15 = 0,20 * 0,10 * 15 = 0,30 çevrimdir; toplam CPI = 1 + 0,30 = 1,30 olur.'),
  ('Statik dallanma öngörüsünde sık kullanılan "geriye doğru dallanmaları alınır (taken), ileriye doğru dallanmaları alınmaz (not-taken) say" (BTFN) kuralının yüksek başarı göstermesinin temel nedeni nedir?', 'Programlardaki döngü sonu dallanmalarının geriye doğru olması ve döngülerin çoğunlukla tekrar etmesi', ['Alt programlardan dönüş komutlarının her zaman ileriye doğru yüksek adreslere atlaması', 'İleriye doğru dallanmaların donanımda hiçbir zaman koşul kontrolü içermemesi', 'Derleyicilerin tüm if-else bloklarını geriye doğru dallanma olacak biçimde ters çevirmesi'], 'Döngüler başlangıç adresine (daha küçük adrese, yani geriye) atlar ve son tur hariç her turda dallanma gerçekleşir; BTFN kuralı donanım tablosu olmadan bu davranışı yakalar.'),
  ('Dallanma yönü doğru tahmin edilse bile hedef adresin hesaplanmasını beklemeden hemen bir sonraki çevrimde hedef adresten komut çekebilmek için IF aşamasında kullanılan donanım önbelleği hangisidir?', 'Dallanma Hedef Tamponu (BTB - Branch Target Buffer)', ['Çevrim Bakma Tamponu (TLB - Translation Lookaside Buffer)', 'Mağaza Yönlendirme Tamponu (Store Buffer)', 'Yazmaç Yeniden Adlandırma Tablosu (RAT)'], 'BTB, dallanma komutunun kendi program sayacı (PC) adresiyle indekslenir ve dallanmanın gideceği hedef PC adresini IF aşamasında anında sağlar.'),
  ('Koşullu kısa if-else bloklarında dallanma komutu kullanmak yerine her iki koldaki komutları koşullu yürütme bayraklarıyla (predicated execution / CMOV) çalıştırmanın temel avantajı nedir?', 'Tahmini zor dallanmalarda yüksek maliyetli yanlış tahmin ve boru hattı temizleme cezasını ortadan kaldırmak', ['Ana bellekteki sayfa tablosu erişim sayısını yarıya indirerek TLB isabetini artırmak', 'Fiziksel yazmaç dosyasındaki okuma portu ihtiyacını tamamen sıfırlamak', 'Sabit diskten yapılan istek üzerine sayfalama işlemlerini arka planda hızlandırmak'], 'Koşullu taşıma (CMOV) veya yüklemli komutlar kontrol akışını doğrusal tutar; birkaç fazladan komut yürütülse bile 15-20 çevrimlik yanlış dallanma cezasından kaçınılır.'),
  ('İşletim sisteminin standart 4 KB sayfalar yerine yoğun bellek kullanan veritabanı veya bilimsel uygulamalarda "Büyük Sayfalar" (Huge Pages, örneğin 2 MB) kullanmasının birincil kazanımı nedir?', 'Aynı sayıda TLB girdisiyle çok daha geniş bir bellek alanını kapsayarak TLB ıskalarını azaltmak', ['Çok küçük süreçlerde son sayfada oluşan iç parçalanma miktarını en aza indirmek', 'İstek üzerine sayfalama sırasında diskten tek seferde okunan veri miktarını küçültmek', 'Boru hattındaki aritmetik komutlar arasındaki RAW veri bağımlılıklarını çözmek'], '2 MB sayfa boyutu, 4 KB sayfaya kıyasla tek bir TLB girdisinin 512 kat daha büyük bellek bölgesini temsil etmesini sağlayarak TLB kapsama alanını genişletir.'),
  ('Aynı dosya sistemi üzerinde mevcut bir dosyaya katı bağ (hard link) oluşturulduğunda aşağıdakilerden hangisi gerçekleşir?', 'İlgili inode yapısındaki bağ sayacı (link count) bir artar', ['Diskte dosyanın veri bloklarının birebir fiziksel kopyası oluşturulur', 'Hedef dosyanın yolunu metin olarak tutan yeni bir inode tahsis edilir', 'Orijinal dosyanın erişim izinleri salt okunur duruma dönüştürülür'], 'Katı bağ yeni bir dizin girişini mevcut inode numarasına bağlar ve yalnızca bağ sayacını artırır.'),
  ('Sembolik bağ (symbolic link) ile katı bağ (hard link) arasındaki temel mimari fark nedir?', 'Sembolik bağın kendine ait ayrı bir inode numarası vardır ve hedef dosyanın yolunu saklar', ['Sembolik bağ yalnızca aynı disk bölümü içerisindeki dosyalara işaret edebilir', 'Katı bağ oluşturulduğunda orijinal dosya silinse bile verilere erişim tamamen kesilir', 'Katı bağlar dizinler arasında döngüsel referans oluşturmak için standart olarak kullanılır'], 'Sembolik bağ hedef dosya yolunu metin olarak barındıran bağımsız bir inode nesnesidir; katı bağ ise aynı inode\'u paylaşır.'),
  ('Disk üzerinde 1 inode numaralı bir dosyaya ek olarak 2 adet katı bağ (hard link) ve 1 adet sembolik bağ oluşturulmuştur. Bu dosyanın inode yapısındaki bağ sayacı (link count) kaçtır?', '3', ['4', '2', '1'], 'Orijinal dizin girişi (1) ve eklenen 2 katı bağ aynı inode\'u paylaştığı için sayaç 3 olur; sembolik bağ sayacı etkilemez.'),
  ('Günlüklemeli (journaling) bir dosya sisteminde veri yazma işlemi sırasında tam günlükleme yapılmadan önce elektrik kesilirse sistem yeniden başladığında ne yapılır?', 'Tamamlanmamış (commit edilmemiş) günlük kaydı yok sayılarak dosya sistemi önceki tutarlı durumuna bırakılır', ['Diskteki tüm veri blokları baştan sona taranarak eksik baytlar eşlik bitleriyle hesaplanır', 'Yarım kalan işlemin veri blokları rastgele sıfırlanarak dosya boyutu maksimuma çıkarılır', 'İşletim sistemi ilgili disk bölümünü kalıcı olarak salt okunur kipte kilitler'], 'Günlüğe tam olarak onay (commit) kaydı düşülmemiş işlemler geri alınır veya yok sayılır, böylece yapısal bozulma önlenir.'),
  ('Günlüklemeli dosya sistemlerinde "yalnızca üst veri günlükleme" (metadata-only journaling) kipinin temel çalışma mantığı nedir?', 'Yalnızca inode, dizin ve boş blok haritası gibi yapısal değişiklikleri günlüğe yazıp asıl dosya verisini doğrudan diske yazmak', ['Dosya içeriklerini şifreleyerek günlüğe yazıp dosya adlarını günlük dışında tutmak', 'Yalnızca sistem yöneticisine (root) ait dosyaların hem verisini hem üst verisini günlüğe kaydetmek', 'Bellekteki tüm önbellek sayfalarını her saniye başı sıkıştırarak günlük alanına kopyalamak'], 'Üst veri günlükleme (ör. ext4 ordered/writeback kipleri) dosya sistemi ağacının bozulmasını önlerken tam veri günlüklemenin yazma yükünü azaltır.'),
  ('Sabit boyutlu bloklar (örneğin 4 KB) kullanan bir dosya sisteminde "iç parçalanma" (internal fragmentation) ne zaman ortaya çıkar?', 'Dosya boyutu blok boyutunun tam katı olmadığında son blokta kullanılmayan boş alan kaldığında', ['Büyük bir dosya diskin farklı silindirlerindeki boşluklara bölünerek yazıldığında', 'Aynı dosyaya birden fazla sembolik bağ oluşturularak dizin tablosu şişirildiğinde', 'Günlükleme alanı dolduğu için işlemlerin ana bellekte bekletildiği durumlarda'], 'Örneğin 4 KB bloklu bir sistemde 1 KB\'lık bir dosya saklandığında kalan 3 KB başka dosyaya verilemez; bu iç parçalanmadır.'),
  ('Blok boyutu 8 KB olan bir dosya sisteminde 25 KB büyüklüğünde bir metin dosyası kaydedildiğinde iç parçalanma nedeniyle boşa giden disk alanı kaç KB olur?', '7 KB', ['1 KB', '8 KB', '3 KB'], '25 KB veri için 4 adet 8 KB\'lık blok (toplam 32 KB) ayrılır; 32 - 25 = 7 KB son blokta kullanılmadan kalır.'),
  ('Bir inode yapısında 12 adet doğrudan (direct) blok işaretçisi ve 1 adet tekli dolaylı (single indirect) blok işaretçisi bulunmaktadır. Blok boyutu 4 KB ve her blok adresi 4 bayt ise, bu inode ile adreslenebilecek en büyük dosya boyutu kaç KB olur?', '4144 KB', ['4096 KB', '1036 KB', '8240 KB'], '12 doğrudan blok = 48 KB. Tekli dolaylı blokta 4096 / 4 = 1024 işaretçi vardır; 1024 * 4 KB = 4096 KB. Toplam: 48 + 4096 = 4144 KB.'),
  ('Modern dosya sistemlerinde (ör. ext4, XFS) tek tek blok işaretçileri yerine kullanılan "kapsam" (extent) yapısının çalışma prensibi nedir?', 'Ardışık fiziksel bloklardan oluşan geniş bir alanı tek bir başlangıç adresi ve blok uzunluğu çiftiyle temsil etmek', ['Her veri bloğunun sonuna bir sonraki bloğun adresini bağlı liste (linked list) şeklinde yazmak', 'Dosya adlarını B-ağacı yerine doğrusal bir dizi içerisinde alfabetik sırasız olarak saklamak', 'Küçük dosyaların tamamını işletim sistemi çekirdeğinin yığın (stack) belleğinde kalıcı olarak tutmak'], 'Extent yapısı binlerce ardışık blok için binlerce ayrı işaretçi tutmak yerine (başlangıç bloğu, uzunluk) bilgisiyle üst veri yükünü ve parçalanmayı azaltır.'),
  ('Basit bağlı liste (linked allocation) kullanan bir dosya sisteminde (tablo önbelleğe alınmadığında) dosyanın ortasındaki bir bayta rastgele erişmek neden çok yavaştır?', 'Hedef bloğun adresini bulmak için dosyanın ilk bloğundan başlayarak aradaki tüm blokların sırayla diskten okunması gerektiğinden', ['Bağlı listedeki her bloğun farklı bir şifreleme algoritmasıyla çözülmesi zorunlu olduğundan', 'İşletim sistemi her blok geçişinde kullanıcıdan yeniden yetki doğrulaması istediğinden', 'Bağlı liste yapısında blok boyutlarının her adımda yarı yarıya küçülmesi gerektiğinden'], 'İşaretçiler blokların içinde tutulduğunda N. bloğa ulaşmak için önceki N-1 bloğu fiziksel olarak okumak gerekir.'),
  ('Unix/Linux sistemlerinde açık bir dosyayı okumakta olan bir süreç (process) çalışırken başka bir süreç rm komutuyla bu dosyayı silerse ne olur?', 'Dizin girişi kaldırılır ve bağ sayacı sıfırlanır ancak açık dosya tanımlayıcısı kapanana kadar inode ve veri blokları diskten silinmez', ['Dosyayı okuyan süreç anında çökerek bellek erişim hatası (segmentation fault) üretir', 'Silme komutu okuyan süreç sonlanana kadar işletim sistemi tarafından sonsuza dek askıya alınır', 'Dosyanın veri blokları anında sıfırlanır ve okuyan sürece yalnızca boş karakterler döndürülür'], 'Çekirdek hem diskteki bağ sayacının (link count = 0) hem de bellekteki açık dosya referans sayacının sıfırlanmasını bekler.'),
  ('Yazma sırasında kopyalama (Copy-on-Write / CoW) kullanan dosya sistemleri (ör. ZFS, Btrfs) elektrik kesintilerine karşı tutarlılığı nasıl sağlar?', 'Mevcut veri ve üst veri bloklarının üzerine asla doğrudan yazmayıp değişiklikleri yeni boş bloklara yazarak kök işaretçiyi en son atomik olarak güncelleyerek', ['Her yazma işleminden önce tüm sabit diskin tam yedeğini ayrı bir manyetik teyp sürücüsüne aktararak', 'Dosya boyutlarını sabit 512 bayt ile sınırlandırarak tek sektörlük yazma garantisine sığınarak', 'Elektrik kesintisi anında işlemci önbelleğindeki verileri ses kartı tampon belleğine yönlendirerek'], 'CoW mimarisinde eski ağaç yapısı yeni bloklar tamamen diske yazılıp kök düğüm değişene kadar bozulmadan kalır.'),
  ('Bir dizinin içerisine 5 adet normal dosya ve 3 adet alt dizin oluşturulduğunda, bu üst dizinin inode yapısındaki bağ sayacı (link count) kaç olur?', '5', ['8', '10', '2'], 'Başlangıçta 2 olan sayaç, her alt dizinin içindeki .. (iki nokta) girişi üst dizine katı bağ yaptığı için 2 + 3 = 5 olur; normal dosyalar üst dizinin sayacını artırmaz.'),
  ('Bir dosya sisteminde blok boyutunun 512 bayttan 64 KB\'a çıkarılmasının performans ve depolama verimliliği üzerindeki temel etkisi nedir?', 'Ardışık büyük dosya aktarım hızı ve üst veri verimliliği artarken, küçük dosyalarda iç parçalanma kaynaklı alan kaybı büyür', ['Küçük dosyalarda iç parçalanma tamamen yok olurken büyük dosyaların okuma hızı yarı yarıya düşer', 'Dosya sisteminin adresleyebileceği maksimum bölüm boyutu küçülürken inode tablosu büyür', 'Rastgele küçük yazma işlemlerinde kafa arama süresi azalırken günlükleme ihtiyacı ortadan kalkar'], 'Büyük bloklar G/Ç işlem sayısını azaltıp ardışık verimi artırır, ancak bloktan küçük her dosyada kullanılmayan alan (iç parçalanma) artar.'),
  ('Günlüklemesiz (non-journaling) bir dosya sisteminde ani güç kesintisi sonrası fsck çalıştırılmasının saatler sürebilmesinin temel nedeni nedir?', 'Hangi blokların yetim kaldığını veya çift tahsis edildiğini bulmak için tüm diskteki bütün inode ve dizin yapılarını baştan sona taramak zorunda kalması', ['Aracın diskteki tüm kullanıcı dosyalarını virüs imzalarına karşı bayt bayt kontrol etmesi', 'Sabit diskin dönüş hızının onarım kipinde güvenlik amacıyla dakikada 100 devire düşürülmesi', 'Kurtarma sırasında tüm verilerin ağ üzerinden uzak bir yedekleme sunucusuna yüklenmesi'], 'Günlük olmadığında hangi işlemin yarım kaldığı bilinmez; tüm üst veri grafiğinin taranması disk boyutuyla doğru orantılı zaman alır.'),
  ('Bir donanım kesmesi (hardware interrupt) işlemciye ulaştığında işletim sisteminin doğru kesme servis rutinini (ISR) bulmak için başvurduğu bellek tablosu hangisidir?', 'Kesme vektör tablosu (Interrupt Vector Table / IDT)', ['Dosya tahsis tablosu (File Allocation Table)', 'Sayfa çerçeve tablosu (Page Frame Table)', 'Düğüm eşleme tablosu (Inode Bitmap)'], 'Kesme numarası kesme vektör tablosunda indeks olarak kullanılarak ilgili kesme işleyici (handler) fonksiyonunun bellek adresine sıçranır.'),
  ('Bir kesme (interrupt) işlenmeye başlanmadan hemen önce işlemcinin ve işletim sisteminin yapmak zorunda olduğu en kritik işlem nedir?', 'O an çalışmakta olan sürecin program sayacını (PC) ve yazmaç (register) durumunu kaydederek kesme bitiminde kaldığı yerden devam etmesini sağlamak', ['Sabit diskteki tüm açık dosyaları kapatıp dosya sistemini geçici olarak devre dışı bırakmak', 'Ana bellekteki tüm kullanıcı süreçlerini takas alanına (swap) taşıyarak RAM\'i tamamen boşaltmak', 'Sistemdeki diğer tüm çevre birimlerinin güç beslemesini keserek veri yolu çakışmasını önlemek'], 'Kesme eşzamansız geldiği için kesilen programın bağlamı (PC, bayraklar, yazmaçlar) yığına kaydedilmezse geri dönüşte hesaplama bozulur.'),
  ('Çok düşük gecikmeli ve işlemi birkaç nanosaniyede tamamlayan çok hızlı bir donanım aygıtı için yoklama (polling) yönteminin kesmeye (interrupt) göre daha verimli olabileceği durum hangisidir?', 'Aygıtın yanıt süresinin, kesme alma ve bağlam değiştirme (ISR giriş-çıkış) maliyetinden daha kısa olduğu durumlar', ['Sistemde aynı anda yüzlerce ağır hesaplama yapan kullanıcı sürecinin çalıştığı çok kullanıcılı sunucular', 'Veri aktarımının saatte yalnızca bir kez gerçekleştiği sıcaklık sensörü okuma işlemleri', 'İşlemcinin pil tasarrufu için derin uyku (deep sleep) kipine girmesinin hedeflendiği mobil cihazlar'], 'Kesme işleme (bağlam kaydetme, önbellek kirliliği, geri yükleme) yüzlerce döngü sürebilir; aygıt 20 döngüde yanıt veriyorsa yoklama daha az toplam CPU zamanı harcar.'),
  ('DMA (Doğrudan Bellek Erişimi) kullanılarak diskten belleğe 4 MB büyüklüğünde bir blok okunurken işlemci (CPU) ne zaman kesme (interrupt) alır?', '4 MB\'lık veri bloğunun tamamı belleğe aktarıldıktan sonra işlem bittiğinde tek bir kez', ['Diskten okunan her bir bayt ana belleğe yazıldığında ayrı ayrı', 'Disk kafası her yeni sektöre geçiş yaptığında senkronizasyon amacıyla', 'DMA denetleyicisi sistem veri yolunu (bus) her kullandığında izin istemek için'], 'Programlı G/Ç veya kesme güdümlü bayt aktarımının aksine DMA tüm bloğu aktarır ve yalnızca transfer tamamlandığında (veya hata oluştuğunda) tek kesme üretir.'),
  ('Kesme güdümlü (DMA\'sız) G/Ç kullanan bir sistemde her 4 baytlık kelime (word) aktarımında bir kesme oluşmaktadır. 16 KB\'lık bir veriyi aktarmak için işlemci kaç kez kesmeye uğrar?', '4096', ['16384', '1', '512'], '16 KB = 16 * 1024 = 16.384 bayttır. Her 4 baytta bir kesme üretildiğinden 16.384 / 4 = 4096 kesme oluşur (DMA olsaydı 1 kesme yeterli olurdu).'),
  ('Sanal bellek kullanan modern sistemlerde dağınık fiziksel sayfa çerçevelerine tek seferde DMA aktarımı yapılabilmesini sağlayan tekniğe ne ad verilir?', 'Dağıt-Topla DMA (Scatter-Gather DMA)', ['Yoklamalı G/Ç (Programmed I/O)', 'Sektör kaydırma (Sector slipping)', 'İkili günlükleme (Dual journaling)'], 'Scatter-Gather DMA, bir tanımlayıcı listesi (descriptor list) alarak sanal olarak bitişik ama fiziksel olarak dağınık bellek bölgelerine tek komutla aktarım yapar.'),
  ('G/Ç mimarisinde "Bellek Eşlemeli G/Ç" (Memory-Mapped I/O) yaklaşımının temel özelliği nedir?', 'Aygıt yazmaçlarının sistemin standart bellek adres uzayına yerleştirilerek normal bellek okuma/yazma buyruklarıyla kontrol edilmesi', ['Çevre birimlerine erişmek için işlemcide yalnızca özel IN ve OUT makine dili buyruklarının kullanılmasının zorunlu olması', 'Tüm çevre birimi verilerinin önce sabit diskteki takas (swap) dosyasına yazılıp oradan okunması', 'Aygıt sürücülerinin çekirdek kipi yerine yalnızca kullanıcı kipindeki tarayıcı süreçlerinde çalıştırılması'], 'Bellek eşlemeli G/Ç\'de ayrı bir G/Ç adres uzayı yoktur; standart LOAD/STORE buyrukları belirli adres aralıklarında aygıt yazmaçlarına yönlendirilir.'),
  ('Her biri 2 TB kapasiteye sahip 4 adet sabit disk kullanılarak oluşturulan bir RAID 0 dizisinde toplam kullanılabilir net depolama kapasitesi kaç TB olur?', '8 TB', ['4 TB', '6 TB', '2 TB'], 'RAID 0 yedeklilik için alan ayırmaz; tüm disklerin kapasitesi toplanır: 4 * 2 TB = 8 TB.'),
  ('Her biri 4 TB kapasiteye sahip 2 adet disk ile kurulan bir RAID 1 dizisinde kullanıcıya sunulan net depolama kapasitesi kaç TB olur?', '4 TB', ['8 TB', '6 TB', '2 TB'], 'RAID 1 veriyi ikinci diske aynaladığı için toplam ham kapasitenin yarısı (4 TB) net depolama alanı olarak kullanılır.'),
  ('Her biri 3 TB büyüklüğünde 5 adet özdeş disk kullanılarak oluşturulan bir RAID 5 dizisinin kullanılabilir net depolama kapasitesi kaç TB\'tır?', '12 TB', ['15 TB', '9 TB', '6 TB'], 'RAID 5\'te net kapasite (N - 1) * Disk Boyutu formülüyle hesaplanır: (5 - 1) * 3 TB = 12 TB.'),
  ('RAID 5 mimarisinde en fazla kaç fiziksel diskin aynı anda arızalanması durumunda hiçbir veri kaybı yaşanmadan sistem çalışmaya devam edebilir?', '1', ['2', '3', '0'], 'Tek eşlik (single parity) kullanan RAID 5 yalnızca 1 disk kaybına tahammül edebilir; ikinci bir disk bozulursa tüm dizi verisi kaybedilir.'),
  ('Rastgele küçük yazma (random small write) trafiğinin çok yoğun olduğu kritik bir veritabanı sunucusunda hem yüksek yazma hızı hem de disk arızasına karşı koruma istendiğinde RAID 5 yerine RAID 10 (1+0) seçilmesinin nedeni nedir?', 'RAID 10\'da eşlik (parity) hesaplama ve okuma-değiştirme-yazma cezası olmadığından küçük yazmalarda yalnızca 2 paralel yazma işlemi yapılması', ['RAID 10\'un aynı sayıda diskle RAID 5\'e kıyasla çok daha yüksek net depolama kapasitesi sunması', 'RAID 10 kurulumunun yalnızca 2 adet fiziksel disk ile gerçekleştirilebilmesi', 'RAID 5\'in sıralı (sequential) okuma işlemlerinde tek bir diskten daha yavaş çalışması'], 'RAID 5 küçük yazmalarda 4 G/Ç cezası öderken RAID 10 aynalanmış çiftlere şeritleme yaparak 2 yazma ile yüksek IOPS ve düşük gecikme sunar.'),
  ('Farklı boyutlarda (1 TB, 2 TB, 4 TB ve 4 TB) 4 adet sabit disk kullanılarak standart bir RAID 5 dizisi oluşturulduğunda kullanılabilir toplam net kapasite kaç TB olur?', '3 TB', ['7 TB', '8 TB', '10 TB'], 'Standart RAID dizilerinde her diskten en küçük diskin boyutu (1 TB) kadar alan kullanılır; 4 diskli RAID 5\'te (4 - 1) * 1 TB = 3 TB net alan elde edilir.'),
  ('Bir RAID 1 dizisinde okuma ve yazma performansları tek bir diske kıyasla teorik olarak nasıl bir davranış sergiler?', 'Okuma istekleri iki diske paralel dağıtılarak hızlanabilirken, yazma işlemi her iki diske de yapıldığından tek disk hızıyla sınırlı kalır', ['Hem okuma hem de yazma hızı disk sayısıyla çarpılarak tam iki katına çıkar', 'Aynalama kontrolü nedeniyle okuma hızı yarıya düşerken yazma hızı dört katına çıkar', 'Okuma işlemleri yalnızca birincil diskten yapılabildiği için okuma hızı değişmez, yazma hızı ikiye katlanır'], 'Akıllı bir RAID 1 denetleyicisi farklı okuma isteklerini iki diske paylaştırarak okuma IOPS değerini ikiye katlayabilir; ancak her yazma iki diske de gitmelidir.'),
  ('Dakikada 7200 devir (7200 RPM) hızla dönen mekanik bir sabit diskte hedef sektörün okuma kafasının altına gelmesi için beklenen "ortalama dönme gecikmesi" (average rotational latency) kaç milisaniyedir?', '4,17 ms', ['8,33 ms', '2,08 ms', '10,00 ms'], '7200 RPM disk saniyede 7200 / 60 = 120 tam tur atar. 1 tam tur 1000 / 120 = 8,33 ms sürer. Ortalama dönme gecikmesi yarım turdur: 8,33 / 2 ≈ 4,17 ms.'),
  ('Mekanik disklerde G/Ç isteklerini geliş sırasına (FCFS) göre değil de asansör mantığıyla kafa hareket yönündeki en yakın silindirlere göre sıralayan "TARAMA" (SCAN) zamanlama algoritmasının amacı nedir?', 'Kafanın disk yüzeyinde ileri geri gereksiz savrulmasını önleyerek toplam arama süresini (seek time) en aza indirmek', ['Dosyaların inode numaralarını küçükten büyüğe doğru yeniden numaralandırmak', 'DMA denetleyicisinin bellek veri yolunda döngü çalma yapmasını tamamen engellemek', 'SSD sürücülerdeki aşınma dengeleme (wear leveling) tablolarını sıfırlamak'], 'FCFS uzak silindirler arasında sürekli git-gel (thrashing) yaratabilirken SCAN (asansör) algoritması tek yönde süpürme yaparak mekanik hareketi azaltır.'),
  ('Unix/Linux sistemlerinde bir sürecin (process) açtığı dosyayı temsil eden küçük negatif olmayan tam sayıya (0, 1, 2, 3...) ne ad verilir ve ne işe yarar?', 'Dosya tanımlayıcısı (File descriptor); sürecin açık dosya tablosundaki ilgili girişe hızlı indeks sağlar', ['Inode numarası; dosyanın fiziksel sabit disk üzerindeki sektör adresini doğrudan tutar', 'Kesme vektörü; dosyanın hangi G/Ç aygıtından okunacağını işlemciye donanımsal olarak bildirir', 'Eşlik anahtarı; dosya okunurken oluşabilecek bit hatalarını XOR yöntemiyle düzeltir'], 'Dosya tanımlayıcısı süreç bazlı bir indekstir ve çekirdekteki sistem geneli açık dosya tablosuna (dosya ofseti ve erişim kipi bilgisine) işaret eder.'),
  ('Bir dosya sistemini mevcut dizin ağacındaki belirli bir dizine (ör. /mnt/veri) bağlayarak erişilebilir hale getirme işlemine ne ad verilir?', 'Bağlama (Mounting)', ['Biçimlendirme (Formatting)', 'Şeritleme (Striping)', 'Bölümleme (Partitioning)'], 'Mounting işlemi harici bir disk bölümünün kök dizinini ana dosya sistemi ağacındaki bir bağlama noktasına (mount point) ekler.'),
  ('SSD sürücülerin içindeki Flash Çeviri Katmanı\'nın (FTL) uyguladığı "Aşınma Dengeleme" (Wear Leveling) mekanizmasının amacı nedir?', 'Silme/yazma işlemlerini tüm NAND flash bloklarına eşit dağıtarak sık güncellenen mantıksal blokların belirli fiziksel hücreleri erken bozmasını önlemek', ['Dosya sistemindeki sembolik bağların ve katı bağların sayısını birbirine eşitlemek', 'Sürücünün güç tüketimini düşürmek için tüm dosyaları tek bir fiziksel blokta toplamak', 'DMA aktarımları sırasında işlemciye gönderilen kesme sinyallerinin voltajını dengelemek'], 'NAND hücreleri sınırlı sayıda programlama/silme döngüsüne dayanır; FTL mantıksal blok adreslerini sürekli farklı fiziksel bloklara eşleyerek ömrü uzatır.'),
  ('Karakter aygıtları (klavye, fare, seri port) ile blok aygıtları (HDD, SSD, NVMe) arasındaki temel G/Ç soyutlama farkı nedir?', 'Blok aygıtları sabit boyutlu bloklar halinde rastgele adreslenebilir ve önbelleklenebilirken, karakter aygıtları bayt akışı (stream) şeklinde sıralı veri sunar', ['Karakter aygıtları yalnızca DMA üzerinden çalışabilirken, blok aygıtları yalnızca yoklama (polling) ile çalışır', 'Blok aygıtlarının üzerine dosya sistemi kurulamazken, karakter aygıtları doğrudan RAID 5 dizisine dahil edilebilir', 'Karakter aygıtları verileri elektrik kesildiğinde kalıcı olarak saklarken, blok aygıtları tüm veriyi kaybeder'], 'Blok aygıtlarında belirli bir sektör/blok numarasına doğrudan seek yapılabilir ve sayfa önbelleği kullanılır; karakter aygıtları ise doğrusal akış üretir veya tüketir.'),
  ('Sektör boyutu 512 bayt olan bir diskte her blok 8 sektörden oluşmaktadır. Dosya sistemi 100 numaralı mantıksal bloğa (0\'dan başlayarak) erişmek istediğinde bölüm başlangıcından itibaren kaçıncı sektöre gitmelidir?', '800', ['108', '51200', '400'], 'Her mantıksal blok 8 fiziksel sektör kapladığından, 0 tabanlı 100. blok 100 * 8 = 800. sektörden başlar.'),
  ('Sayfa tablosunun bellekte aşırı büyük yer kaplamasını önlemek için kullanılan yaygın mimari çözüm hangisidir?', 'Çok düzeyli sayfalama', ['Sabit boyutlu tek tablo', 'Önbelleksiz fiziksel erişim', 'Sayfa boyutunu bir bayt yapma'], 'Çok düzeyli sayfalama, yalnızca kullanılan adres aralıkları için alt sayfa tabloları ayırarak bellek tüketimini azaltır.'),
  ('4 KB sayfa boyutuna sahip bir sistemde 32 bitlik sanal adresin kaç biti sayfa içi ofset (kaydırma) için kullanılır?', '12 bit', ['16 bit adres alanı', '20 bit çerçeve numarası', '8 bit bayt göstergesi'], '4 KB = 2^12 bayt olduğundan sayfa içindeki her baytı adreslemek için 12 ofset biti gerekir.'),
  ('32 bitlik sanal adres uzayı ve 4 KB sayfa boyutu olan bir sistemde sanal sayfa numarası (VPN) kaç bittir?', '20 bit', ['12 bit sayfa ofseti', '24 bit fiziksel etiket', '10 bit küme indeksi'], '32 bitten 12 ofset biti çıkarıldığında sanal sayfa numarası için 32 - 12 = 20 bit kalır.'),
  ('Bir sistemde TLB isabet oranı yüzde 90, TLB erişim süresi 1 ns ve ana bellek erişim süresi 100 ns ise etkin bellek erişim süresi yaklaşık kaç ns olur?', '111 ns', ['101 ns etkin süre', '201 ns maksimum gecikme', '91 ns ortalama süre'], 'İsabet durumunda 1+100=101 ns (%90), ıskada TLB+sayfa tablosu+veri=1+100+100=201 ns (%10); toplam 0,9×101 + 0,1×201 = 111 ns olur.'),
  ('FIFO sayfa değiştirme algoritmasında çerçeve sayısı artırıldığı hâlde sayfa hatası sayısının artabilmesi olgusuna ne ad verilir?', 'Belady anomalisi', ['Amdahl kısıtlaması', 'Moore sapması kuralı', 'Thrashing döngüsü'], 'Belady anomalisi, FIFO gibi yığın özelliğine sahip olmayan algoritmalarda daha fazla RAM çerçevesiyle daha çok sayfa hatası çıkmasıdır.'),
  ('Aşağıdaki sayfa değiştirme algoritmalarından hangisi Belady anomalisinden etkilenmez?', 'LRU', ['FIFO değiştirme yöntemi', 'Rastgele sayfa seçimi', 'Basit dairesel liste'], 'LRU yığın (stack) özelliğini sağladığı için çerçeve sayısı arttığında mevcut sayfalar kümesi büyür ve sayfa hatası artmaz.'),
  ('3 boş çerçeveli bir bellekte "1, 2, 3, 4, 1, 2" sayfa erişim dizisi FIFO ile işlendiğinde toplam kaç sayfa hatası oluşur?', '6', ['4 sayfa yükleme hatası', '3 başlangıç sayfa hatası', '5 bellek erişim hatası'], 'Sırasıyla [1], [1,2], [1,2,3], [4,2,3] (1 çıktı), [4,1,3] (2 çıktı), [4,1,2] (3 çıktı) biçiminde her 6 erişim sayfa hatası üretir.'),
  ('3 boş çerçeveli bir bellekte "1, 2, 3, 1, 4" sayfa erişim dizisi LRU ile işlendiğinde 4 geldiğinde hangi sayfa çıkarılır?', '2', ['1 numaralı sayfa bloğu', '3 numaralı sayfa bloğu', '4 numaralı yeni sayfa'], '4 geldiğinde en son erişilenler 1 ve 3 olduğundan en uzun süredir kullanılmayan sayfa 2\'dir.'),
  ('Sanal bellekte gelecekte en uzun süre kullanılmayacak sayfayı çıkaran kuramsal en iyi algoritma hangisidir?', 'Belady\'nin optimal algoritması', ['İkinci şans saat algoritması', 'En az kullanılan sıklık yöntemi', 'İlk giren ilk çıkar kuyruğu'], 'Optimal (OPT/MIN) algoritma geleceği bildiği varsayıldığı için pratikte uygulanamaz ama diğer algoritmalar için üst sınır kıstasıdır.'),
  ('Bir sürecin aktif çalışma döneminde düzenli olarak ihtiyaç duyduğu sayfalar kümesine ne ad verilir?', 'Çalışma kümesi', ['Sayfa hatası havuzu', 'Çerçeve paylaşım tablosu', 'Boş blok listesi'], 'Çalışma kümesi (working set), belirli bir zaman penceresinde sürecin aktif kullandığı sayfaları ifade eder ve thrashing\'i önlemede kullanılır.'),
  ('İşletim sistemi thrashing yaşadığını tespit ettiğinde sorunu çözmek için en etkili adım hangisidir?', 'Çoklu programlama derecesini azaltmak', ['İşlemci saat frekansını yarıya indirmek', 'Sayfa tablosu girişlerini silmek', 'Boru hattı aşamalarını kapatmak'], 'Çoklu programlama derecesini düşürerek bazı süreçleri askıya almak, kalan süreçlere çalışma kümelerine yetecek çerçeve sağlar.'),
  ('İç parçalanma (internal fragmentation) sayfalamalı bellek yönetiminde nerede ortaya çıkar?', 'Sürecin son sayfasındaki kullanılmayan boşlukta', ['İki farklı fiziksel çerçeve arasındaki boşlukta', 'TLB içindeki geçersiz etiket alanlarında', 'İşlemci yazmaçları arasındaki kaydırma alanında'], 'Sayfalar sabit boyutlu olduğundan bir sürecin belleği sayfa boyutunun tam katı değilse son sayfanın bir kısmı boş kalır.'),
  ('Sayfalamalı sanal bellekte harici parçalanmanın (external fragmentation) görülmemesinin temel nedeni nedir?', 'Tüm çerçevelerin eşit boyutta olması', ['Belleğin sürekli diske kopyalanması', 'Programların aynı boyutta derlenmesi', 'Önbelleğin doğrudan eşlemeli olması'], 'Fiziksel bellek eşit boyutlu çerçevelere ayrıldığı için herhangi bir boş çerçeve herhangi bir sayfaya atanabilir.'),
  ('C/C++ gibi dillerde iki boyutlu bir matrisi satır-öncelikli (row-major) düzende bellekten okurken hangi tarama yöntemi mekân yerelliğinden en iyi yararlanır?', 'Satır satır taramak', ['Sütun sütun taramak', 'Köşegen boyunca atlamak', 'Rastgele indekslerle gezmek'], 'Satır-öncelikli yerleşimde aynı satırdaki elemanlar bellekte ardışıktır; satır satır okuma aynı önbellek bloğundan art arda isabet alır.'),
  ('Bir önbelleğin boyutu aynı kalırken doğrudan eşlemeliden 4-yollu küme ilişkiliye geçilirse hangi tür ıskalar azalır?', 'Çakışma ıskaları', ['Zorunlu başlangıç ıskaları', 'Kapasite yetersizliği ıskaları', 'Disk erişim zaman aşımı ıskaları'], 'Aynı kümeye düşen farklı bloklar artık 4 farklı yola sığabildiği için çakışma (conflict) ıskaları azalır.'),
  ('Bir bellek bloğuna programın çalışması boyunca ilk kez erişildiğinde oluşan ve önbellek boyutu büyütülse de tamamen yok edilemeyen ıska türü hangisidir?', 'Zorunlu ıska', ['Çakışma kaynaklı ıska', 'Kapasite yetersizliği ıskası', 'Tutarlılık bozulması ıskası'], 'Zorunlu (compulsory/cold) ıska, bir veri bloğunun önbelleğe ilk defa getirilmesi sırasında kaçınılmaz olarak oluşur.'),
  ('Önbellekteki bir adresin doğru bellek bloğuna ait olup olmadığını doğrulamak için karşılaştırılan adres parçası hangisidir?', 'Etiket', ['Küme indeks biti', 'Blok içi bayt ofseti', 'Çerçeve koruma biti'], 'Aynı indekse eşlenebilen birden çok bellek bloğu olduğundan, etiketin (tag) eşleşmesi aranan bloğun bulunduğunu kanıtlar.'),
  ('64 bayt blok boyutuna ve toplam 256 satıra sahip doğrudan eşlemeli bir önbellekte 32 bit adresin kaç biti etiket (tag) olur?', '18 bit', ['14 bit indeks ve ofset', '20 bit blok göstergesi', '16 bit satır adresi'], 'Blok ofseti log2(64)=6 bit, indeks log2(256)=8 bit olur; kalan 32 - (6 + 8) = 18 bit etikettir.'),
  ('Toplam 16 KB kapasiteli, 64 bayt blok boyutlu ve 4-yollu küme ilişkili bir önbellekte kaç adet küme (set) bulunur?', '64', ['256 toplam önbellek satırı', '128 ikili yol kümesi', '16 doğrudan eşleme kümesi'], 'Toplam blok sayısı 16384 / 64 = 256\'dır; 4-yollu olduğu için küme sayısı 256 / 4 = 64\'tür.'),
  ('Write-back politikasında yazma işleminin ana belleğe yansıtılmasını geciktirmek hangi önemli avantajı sağlar?', 'Bellek veri yolu trafiğini azaltır', ['Ana belleği her an güncel tutar', 'Kirli bit donanımını gereksiz kılar', 'İlk okuma gecikmesini sıfırlar'], 'Aynı önbellek bloğuna yapılan çoklu yazmalar tek bir ana bellek aktarımıyla birleştirildiği için bellek bant genişliği korunur.'),
  ('Önbellek blok boyutunu makul sınırın ötesinde aşırı büyütmek hangi olumsuz sonuca yol açabilir?', 'Iska cezasını ve çakışma ıskalarını artırır', ['Zaman yerelliğini tamamen ortadan kaldırır', 'Etiket bit sayısını iki katına çıkarır', 'Sayfa tablosu boyutunu küçültür'], 'Çok büyük bloklar önbellekteki toplam blok sayısını azaltıp çakışmayı artırır ve ana bellekten taşıma süresini uzatır.'),
  ('Çok çekirdekli işlemcilerde her çekirdeğin kendi L1 önbelleğinde aynı bellek adresinin farklı değerlere sahip olmasını önleyen mekanizmaya ne ad verilir?', 'Önbellek tutarlılığı', ['Sanal sayfa renklendirme', 'Boru hattı yönlendirme', 'Dairesel kilit çözümü'], 'Önbellek tutarlılığı (cache coherence), MESI gibi protokollerle paylaşılan verilerin çekirdekler arası tutarlı kalmasını sağlar.'),
  ('MESI önbellek tutarlılığı protokolündeki "M" harfi ilgili önbellek satırının hangi durumda olduğunu gösterir?', 'Değiştirilmiş (Modified)', ['Paylaşılmış okuma (Shared)', 'Geçersiz kılınmış (Invalid)', 'Tekil temiz (Exclusive)'], 'Modified (M), verinin yalnızca bu önbellekte bulunduğunu ve ana bellekteki değerden farklı olacak şekilde güncellendiğini belirtir.'),
  ('İki farklı iş parçacığı birbirinden tamamen bağımsız iki değişkeni güncellese de bu değişkenler aynı önbellek satırında yer alıyorsa oluşan performans düşüşüne ne ad verilir?', 'Sahte paylaşım', ['Yarış durumu çakışması', 'Ölümcül kilitlenme', 'Doğrudan bellek taşması'], 'Sahte paylaşım (false sharing), aynı önbellek satırının çekirdekler arasında sürekli geçersiz kılınıp taşınmasıyla ciddi yavaşlama yaratır.'),
  ('Kilitlenmenin (deadlock) oluşabilmesi için gerekli dört Coffman koşulundan biri olmayan seçenek hangisidir?', 'Öncelikli kesme', ['Karşılıklı dışlama koşulu', 'Tut ve bekle koşulu', 'Döngüsel bekleme koşulu'], 'Coffman koşulları karşılıklı dışlama, tut ve bekle, kesintisizlik (no preemption) ve döngüsel beklemedir; kesme (preemption) izinliyse kilitlenme önlenebilir.'),
  ('Bir sürecin başka kaynaklar isterken elinde tuttuğu kaynakları bırakmaması hangi Coffman kilitlenme koşuludur?', 'Tut ve bekle', ['Döngüsel bekleme durumu', 'Karşılıklı dışlama kuralı', 'Zorla geri alma yasağı'], 'Tut ve bekle (hold and wait), sürecin mevcut kaynaklarını serbest bırakmadan yeni kaynak beklemesidir.'),
  ('Tüm kaynaklara küresel bir numara verip süreçlerin kaynakları yalnızca artan numara sırasıyla istemesini zorunlu kılmak hangi Coffman koşulunu ortadan kaldırır?', 'Döngüsel bekleme', ['Karşılıklı dışlama koşulu', 'Tut ve bekle koşulu', 'Zorla geri alma yasağı'], 'Artan sıra kuralı, kaynak bekleme grafında kapalı bir döngü oluşmasını matematiksel olarak imkânsız kılar.'),
  ('İkili bir semaforun başlangıç değeri 1 iken üç iş parçacığı peş peşe wait(P) çağrısı yaparsa kaç iş parçacığı bloke olur?', '2', ['1 iş parçacığı bekler', '3 iş parçacığı bekler', 'Hiçbiri beklemez'], 'İlk iş parçacığı değeri 1\'den 0\'a düşürerek geçer; ikinci ve üçüncü iş parçacıkları değer negatifleşeceği veya 0 olduğu için bloke olur.'),
  ('Bir iş parçacığı düşük öncelikli olduğu için kaynaklara uzun süre veya hiç erişemiyorsa bu duruma ne ad verilir?', 'Açlık (starvation)', ['Kilitlenme (deadlock)', 'Yarış durumu (race)', 'Çırpınma (thrashing)'], 'Açlık (starvation), sistem ilerlemeye devam ettiği hâlde belirli bir sürecin sürekli ötelenerek kaynak alamamasıdır.'),
  ('Düşük öncelikli bir iş parçacığının tuttuğu kilidi yüksek öncelikli bir iş parçacığı beklerken orta öncelikli bir işin işlemciyi ele geçirmesiyle oluşan soruna ne ad verilir?', 'Öncelik terslenmesi', ['Döngüsel kilitlenme', 'Sahte önbellek paylaşımı', 'Semafor taşması'], 'Öncelik terslenmesi (priority inversion), yüksek öncelikli görevin dolaylı olarak orta öncelikli görev tarafından geciktirilmesidir.'),
  ('Bir iş parçacığının kilidi beklerken uyku durumuna geçmek yerine döngü içinde sürekli kilidin açılmasını kontrol ettiği kilit türü hangisidir?', 'Dönen kilit', ['Sayma semaforu kilidi', 'Koşul değişkeni bekleyicisi', 'Okuyucu-yazıcı kuyruğu'], 'Dönen kilit (spinlock), çok kısa bekleme sürelerinde bağlam değiştirme maliyetinden kaçınmak için işlemciyi meşgul beklemede tutar.'),
  ('Tek çekirdekli ve kesmesiz bir sistemde dönen kilit (spinlock) kullanmak neden tehlikelidir?', 'Kilidi bırakacak iş parçacığı işlemciyi alamaz', ['Önbellek satırları ana belleğe yazılamaz', 'Sayfa tablosu adresi sıfırlanır', 'Dosya sistemi günlüğü bozulur'], 'Tek çekirdekte meşgul bekleyen iş parçacığı işlemciyi bırakmazsa kilidi tutan diğer iş parçacığı çalışıp kilidi serbest bırakamaz.'),
  ('Semafor işlemlerinin bölünmez biçimde yürütülerek araya başka iş parçacığının girmesini engellemesine hangi özellik denir?', 'Atomiklik', ['Zaman yerelliği', 'Döngüsel bekleme', 'Çoklu adresleme'], 'Atomiklik (atomicity), bir işlemin ya tamamen gerçekleşmesini ya da hiç gerçekleşmemiş gibi bölünmeden korunmasını sağlar.'),
  ('Kilitlenme riskini önden analiz ederek yalnızca güvenli durumlara kaynak tahsis eden ünlü algoritma hangisidir?', 'Banker algoritması', ['Dijkstra en kısa yol algoritması', 'Belady sayfa değiştirme yöntemi', 'Bellman-Ford graf algoritması'], 'Banker (Bankacı) algoritması, her tahsis öncesinde tüm süreçlerin tamamlanabileceği güvenli bir sıralama olup olmadığını denetler.'),
  ('Üretici-tüketici (producer-consumer) probleminde sınırlı tamponun doluluğunu ve boşluğunu izlemek için tipik olarak kaç tür senkronizasyon elemanı birlikte kullanılır?', 'Bir mutex ve iki sayma semaforu', ['Yalnızca tek bir sayfa tablosu', 'Üç adet ikili yazmaç kilidi', 'Sadece bir dönen kilit bayrağı'], 'Tampon erişimi için bir mutex, boş yuvaları sayan bir semafor ve dolu yuvaları sayan ikinci bir semafor kullanılır.'),
  ('Her aşaması 2 ns süren ideal (tehlikesiz) 5 aşamalı bir boru hattında 100 komutun tamamlanması yaklaşık kaç ns sürer?', '208 ns', ['1000 ns toplam süre', '200 ns tam süre', '250 ns çalışma süresi'], 'İlk komut 5 aşamada tamamlanır, sonraki 99 komut her döngüde 1 tane çıkar: (5 + 99) × 2 ns = 104 × 2 = 208 ns.'),
  ('Aynı 5 aşamalı boru hattında aşama gecikmeleri sırasıyla 3, 2, 5, 4 ve 2 ns ise boru hattının minimum saat periyodu en az kaç ns olmalıdır?', '5 ns', ['16 ns toplam gecikme', '3,2 ns ortalama süre', '2 ns en küçük gecikme'], 'Senkron boru hattında saat periyodu en yavaş aşamanın süresinden küçük olamaz; bu nedenle minimum periyot 5 ns\'dir.'),
  ('Veri yönlendirme (forwarding) donanımı bulunan klasik 5 aşamalı RISC boru hattında yine de 1 döngü bekleme (stall) gerektiren tipik veri tehlikesi hangisidir?', 'Load-use tehlikesi', ['ADD sonrası SUB tehlikesi', 'İki bağımsız AND komutu', 'Yazmaçtan yazmaca kopyalama'], 'Bellekten veri okuyan LW komutu veriyi MEM aşaması sonunda üretir; hemen ardından EX aşamasında kullanan komut 1 döngü bekler.'),
  ('Aynı anda hem komut getirme (IF) hem de veri belleği erişimi (MEM) yapan iki komutun tek bir birleşik bellekte çakışması hangi tehlikedir ve nasıl çözülür?', 'Yapısal tehlike; ayrı komut ve veri önbellekleriyle çözülür', ['Kontrol tehlikesi; dal tahmini tablosuyla çözülür', 'Veri tehlikesi; yönlendirme hattıyla çözülür', 'Sayfa tehlikesi; TLB büyütülerek çözülür'], 'Harvard tarzı ayrık L1 komut önbelleği (I-cache) ve L1 veri önbelleği (D-cache), IF ve MEM erişimlerinin çakışmasını engeller.'),
  ('Dallanma tahmini yanlış çıktığında boru hattına yanlış yoldan alınmış komutlara ne yapılır?', 'Boru hattından temizlenir', ['Sonuçları ana belleğe kaydedilir', 'Düşük öncelikli kuyruğa taşınır', 'Disk günlüğüne yedeklenir'], 'Yanlış tahmin edilen spekülatif komutların mimari durumu değiştirmemesi için boru hattı aşamalarından temizlenmesi gerekir.'),
  ('Geriye doğru dallanmaların (döngü sonu gibi) alınacağını, ileriye doğru dallanmaların alınmayacağını varsayan tahmin yöntemi hangisidir?', 'Statik dal tahmini', ['2-bit dinamik dal tahmini', 'İki düzeyli uyarlamalı tahmin', 'Donanım dönüş yığını tahmini'], 'Statik dal tahmini çalışma zamanı geçmişi tutmadan yalnızca komut yönüne veya derleyici ipucuna göre sabit karar verir.'),
  ('1-bit dinamik dal tahmincisinin iç içe döngülerde neden her döngü turunda iki kez yanlış tahmin yapma eğilimi vardır?', 'Döngüden çıkarken ve tekrar girerken durumunu hemen tersine çevirdiği için', ['Döngü sayaçlarını ana bellekten okuduğu için', 'Yalnızca ileri dallanmaları izleyebildiği için', 'Her saat döngüsünde sıfırlandığı için'], '1-bit tahminci döngü çıkışında "alınmaz" durumuna geçer; bir sonraki döngü başlangıcında ilk iterasyonu da yanlış tahmin eder.'),
  ('2-bit doygunluk sayacı (saturating counter) kullanan bir dal tahmincisinin 1-bit tahminciye göre temel üstünlüğü nedir?', 'Tek bir istisna sonucu tahmini hemen değiştirmemesi', ['Hiçbir zaman yanlış tahmin yapmaması', 'Boru hattı aşama sayısını yarıya indirmesi', 'Komut önbelleğine olan ihtiyacı kaldırması'], '2-bit sayaç "güçlü alınır" durumundan "alınmaz" tahminine geçmek için arka arkaya iki yanlış karar gerektirir, döngü çıkış gürültüsünü sönümler.'),
  ('İşlemcinin dallanma hedef adresini hesaplamayı beklemeden önceki hedefleri saklayarak IF aşamasında sunan donanım tablosu hangisidir?', 'Dal hedef tamponu (BTB)', ['Çeviri yan tamponu (TLB)', 'Dosya ayırma tablosu (FAT)', 'Önbellek etiket tablosu'], 'BTB (Branch Target Buffer), dallanma komutunun adresini hedef adresiyle eşleştirerek boru hattının durmadan getirme yapmasını sağlar.'),
  ('Derleyicinin veri veya kontrol tehlikelerini azaltmak için bağımsız komutların sırasını güvenli biçimde yeniden düzenlemesine ne ad verilir?', 'Komut çizelgeleme', ['Sanal bellek sıkıştırma', 'Önbellek renklendirme', 'Dosya sistemi günlükleme'], 'Komut çizelgeleme (instruction scheduling), load-use veya dallanma boşluklarına bağımsız komutlar yerleştirerek baloncukları önler.'),
  ('Her saat döngüsünde birden fazla komutu paralel olarak boru hatlarına gönderebilen işlemci mimarisine ne ad verilir?', 'Süperskaler mimari', ['Tek çevrimli mimari', 'Doğrudan eşlemeli mimari', 'Sıralı disk mimarisi'], 'Süperskaler (superscalar) işlemciler çoklu yürütme birimleri sayesinde döngü başına birden fazla komut (IPC > 1) tamamlayabilir.'),
  ('Gerçek veri bağımlılığı olmadığı hâlde aynı yazmaç adının yeniden kullanılmasından doğan WAR ve WAW sahte bağımlılıklarını donanımda gideren teknik hangisidir?', 'Yazmaç yeniden adlandırma', ['Sayfa tablosu yürütme', 'Statik dal tahmini', 'Sabit disk birleştirme'], 'Yazmaç yeniden adlandırma (register renaming), mimari yazmaçları daha geniş fiziksel yazmaç havuzuna eşleyerek sahte bağımlılıkları ortadan kaldırır.'),
  ('Komutları programdaki yazılış sırasıyla değil, işlenen verileri hazır oldukça yürütüp sonuçları program sırasıyla onaylayan tekniğe ne ad verilir?', 'Sıra dışı yürütme (Out-of-Order)', ['Sıralı toplu işleme (Batch)', 'Doğrudan bellek eşleme (DMA)', 'Sabit zamanlı sayfalama'], 'Out-of-Order (OoO) yürütme, bekleyen komutların arkasındaki hazır komutları çalıştırarak boru hattı verimini artırır; ROB ile sıralı onay sağlar.'),
  ('Boru hattında iki komutun farklı saat döngülerinde aynı donanım aşamasını kullanması sorun çıkarır mı?', 'Hayır, yapısal tehlike aynı anda erişimde oluşur', ['Evet, her komut tüm boru hattını tek başına kilitler', 'Evet, veri yönlendirme bu durumu yasaklar', 'Hayır, çünkü boru hattında saat sinyali yoktur'], 'Boru hattının temel amacı farklı komutların farklı döngülerde aynı birimleri sırayla paylaşarak paralel ilerlemesidir.'),
  ('Unix dosya sisteminde bir dosyanın sert bağlantılarından (hard link) biri silindiğinde dosya verisi ne zaman diskten gerçekten serbest bırakılır?', 'Inode bağlantı sayacı sıfıra indiğinde ve açık dosya kalmadığında', ['İlk oluşturulan dosya adı silindiği anda', 'Dosyanın sembolik bağlantıları silindiği anda', 'İşletim sistemi yeniden başlatıldığı anda'], 'Inode üzerindeki bağlantı sayacı (link count) 0 olup hiçbir süreç dosyayı açık tutmadığında bloklar serbest bırakılır.'),
  ('Bir sert bağlantı (hard link) neden farklı disk bölümleri (partition) veya farklı dosya sistemleri arasında oluşturulamaz?', 'Inode numaraları yalnızca kendi dosya sistemi içinde benzersizdir', ['Sert bağlantılar yalnızca metin dosyalarını destekler', 'Disk bölümleri aynı saat frekansında çalışmaz', 'İşletim sistemi yalnızca tek bir dizine izin verir'], 'Sert bağlantı doğrudan aynı dosya sistemindeki bir inode numarasına bağlandığından başka bir dosya sistemindeki inode\'a işaret edemez.'),
  ('FAT dosya sisteminde çok büyük bir dosyanın tam ortasındaki bir bayta rastgele erişim neden inode tabanlı sistemlere göre daha yavaştır?', 'Küme zincirini baştan itibaren takip etmek gerekebilir', ['FAT dosya sistemi rastgele okumaya izin vermez', 'FAT her blokta veri şifrelemesi uygular', 'FAT yalnızca salt okunur disklerde çalışır'], 'FAT\'ta bloklar bağlı liste mantığıyla zincirlendiğinden ortadaki kümeye ulaşmak için tablo zincirini taramak gerekir (önbelleklenmemişse).'),
  ('ext4 dosya sisteminin ext3\'e kıyasla büyük dosyalarda hem parçalanmayı hem de üst veri yükünü azaltmak için getirdiği ardışık blok aralığı yapısı hangisidir?', 'Extent', ['Çift dolaylı FAT zinciri', 'Sabit boyutlu sektör tablosu', 'Sanal bellek çerçevesi'], 'Extent, tek tek blok numaraları listelemek yerine başlangıç bloğu ve uzunluk çiftiyle ardışık büyük blok aralıklarını tanımlar.'),
  ('Dosya sistemlerinde "ardışık tahsis" (contiguous allocation) yönteminin en büyük dezavantajı nedir?', 'Harici parçalanma ve dosya büyütmede zorluk', ['Sıralı okuma hızının aşırı derecede düşmesi', 'Dosya başlangıç adresinin bulunamaması', 'Süper blok kullanımının imkânsız olması'], 'Ardışık tahsiste dosya genişlediğinde bitişik boş alan yoksa taşınması gerekir ve silinen dosyalar diskte harici boşluklar bırakır.'),
  ('Dosya sistemlerinde "bağlı tahsis" (linked allocation) yönteminde bir bloğun işaretçi alanı bozulursa hangi sorun yaşanır?', 'Zincirin geri kalanındaki tüm bloklara erişim kopar', ['Yalnızca dosyanın ilk baytı okunamaz hâle gelir', 'Diskteki tüm diğer dosyaların izinleri değişir', 'Sistem otomatik olarak ardışık tahsise geçer'], 'Her blok bir sonraki bloğun adresini sakladığı için aradaki bir işaretçinin bozulması sonraki tüm veri bloklarını ulaşılmaz kılar.'),
  ('Unix inode yapısında küçük dosyaların hızlı erişimini korurken çok büyük dosyaları da adresleyebilmek için hangi mekanizma kullanılır?', 'Doğrudan ve çok düzeyli dolaylı blok işaretçileri', ['Yalnızca tek bir doğrudan işaretçi', 'Tüm disk bloklarını içeren sabit bir dizi', 'Rastgele karma tablosu eşlemesi'], 'Inode önce doğrudan blok işaretçileri sunar; dosya büyüdükçe tekli, ikili ve üçlü dolaylı blok işaretçileri devreye girer.'),
  ('Günlüklemeli (journaling) bir dosya sisteminde "metadata-only" (yalnızca üst veri) günlükleme modu ile "full data" (tam veri) günlükleme arasındaki fark nedir?', 'Metadata modu daha hızlıdır ancak çökme anında dosya içeriği güncel olmayabilir', ['Metadata modu her dosya verisini diske iki kez yazar', 'Tam veri modu günlük alanını hiç kullanmaz', 'Tam veri modu dizin yapılarını korumaz'], 'Yalnızca üst veriyi günlüklemek yapısal bütünlüğü hızla korur; tam veri günlükleme ise hem veriyi hem üst veriyi iki kez yazarak güvenlik karşılığı performans öder.'),
  ('SSD (katı hâl sürücüsü) üzerinde geleneksel mekanik disklerdeki gibi sık disk birleştirme (defragmentation) yapmak neden genellikle önerilmez?', 'Rastgele erişim çok hızlıdır ve gereksiz yazmalar SSD ömrünü azaltır', ['SSD\'ler dosyaları parçalanmış biçimde saklayamaz', 'SSD\'lerde dosya sistemi veya inode kavramı yoktur', 'Birleştirme işlemi SSD okuma hızını on kat düşürür'], 'SSD\'de mekanik kafa arama gecikmesi yoktur; ayrıca NAND flash hücreleri sınırlı yazma/silme ömrüne sahiptir.'),
  ('SSD\'lerde silinen dosyaların artık geçersiz olan bloklarını işletim sisteminin sürücüye bildirerek arka planda temizlemesini sağlayan komut hangisidir?', 'TRIM', ['FSYNC komutu', 'FLUSH yazmacı', 'DEFRAG çağrısı'], 'TRIM komutu, SSD denetleyicisine hangi sayfaların artık kullanılmadığını bildirerek yazma performansını ve aşınma dengelemesini iyileştirir.'),
  ('İşletim sisteminin diskteki dosya bloklarını ana bellekte (RAM) geçici olarak saklayarak sonraki okuma ve yazmaları hızlandırdığı yapı hangisidir?', 'Sayfa önbelleği', ['Dal hedef tamponu', 'Çeviri yan tamponu', 'Komut çözümleme kuyruğu'], 'Sayfa önbelleği (page cache / buffer cache), disk G/Ç gecikmesini gizlemek için sık kullanılan dosya verilerini RAM\'de tutar.'),
  ('Bir uygulama yazdığı kritik verinin RAM tamponundan fiziksel diske kalıcı olarak aktarılmasını garanti etmek için hangi sistem çağrısını kullanır?', 'fsync', ['fork sistem çağrısı', 'malloc bellek isteği', 'exec süreç çağrısı'], 'fsync(), ilgili dosyaya ait kirli tampon sayfalarının ve üst verilerin kalıcı depolamaya yazılmasını zorlar.'),
  ('Dosya sistemlerinde diskteki hangi blokların boş, hangilerinin dolu olduğunu her blok için 1 bit ayırarak izleyen yapı hangisidir?', 'Boş alan bit haritası', ['Sert bağlantı tablosu', 'Üçlü dolaylı blok dizisi', 'Önyükleme kayıt tablosu'], 'Bit haritası (free-space bitmap), her bloğu 0 (boş) veya 1 (dolu) bitiyle temsil ederek ardışık boş blok bulmayı hızlandırır.'),
  ('Bir dosya sisteminde blok boyutu 512 bayttan 4 KB\'a çıkarılırsa çok sayıda küçük dosya (örneğin 300 baytlık) saklayan bir diskte ne gözlemlenir?', 'İç parçalanma artar ve kullanılabilir alan israfı büyür', ['İç parçalanma tamamen ortadan kalkar', 'Dosya sayısı iki katına kadar artar', 'Disk üzerindeki inode sayısı yarıya düşer'], 'Her küçük dosya en az bir blok kapladığından 4 KB blokta 300 baytlık dosya 3796 bayt iç parçalanma üretir.'),
  ('Farklı dosya sistemlerinin (ext4, FAT32, NTFS gibi) işletim sistemi çekirdeği tarafından tek ve ortak bir arayüzle kullanılmasını sağlayan soyutlama katmanı hangisidir?', 'Sanal Dosya Sistemi (VFS)', ['Sanal Bellek Yöneticisi (VMM)', 'Donanım Soyutlama Katmanı (HAL)', 'Doğrudan Bellek Erişimi (DMA)'], 'VFS (Virtual File System), open, read, write gibi standart çağrıları alttaki özgül dosya sistemi sürücülerine yönlendirir.'),
  ('Bir dosya açıldığında işletim sisteminin o süreç için dosya konum imlecini (offset) ve erişim modunu takip ettiği süreç içi tamsayı kimliği hangisidir?', 'Dosya tanımlayıcısı', ['Fiziksel sektör numarası', 'Önbellek etiket değeri', 'Sanal sayfa çerçevesi'], 'Dosya tanımlayıcısı (FD), sürecin açık dosya tablosundaki girdiyi gösteren küçük negatif olmayan bir tamsayıdır.'),
  ('Dosya sisteminde ani kapanma sonrası oluşabilecek tutarsızlıkları (örneğin bir bloğun hem boş hem bir dosyaya ait görünmesi) tarayıp onaran geleneksel Unix aracı hangisidir?', 'fsck', ['grep arama aracı', 'top izleme aracı', 'chmod izin aracı'], 'fsck (file system consistency check), süper blok, inode\'lar, dizinler ve blok haritaları arasındaki tutarlılığı denetler.'),
];
